quests[27837] = { id = 27837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trespassers in the Water", description = "Shortly after Uldum's protective barriers fell, the Vir'naal river became afflicted with a terrible corruption.\n\nWhether it was brought here maliciously or accidentally is not of great significance.\n\nThe result is the same.  As the river becomes clouded so does our ability to peer into what the future holds for us.\n\nLook outside, {class}.  These foul creatures were never meant to live in the pristine waters of our river.\n\nSlay them so that the river may grant us visions once again.", sourceObjective = "Slay 8 Stillwater Slitherers.", progress = "You've returned, {race}.", completion = "Yes, {name}.  I can feel the disruption in the river fading.\n\nYet, I feel the source of this taint still lingers.", sourceObjectiveStatus = "unverified-source-field" }
quests[27838] = { id = 27838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Root of the Corruption", description = "You might have dealt with the symptoms of our problem, {name}.  But I've been studying these foul beasts and the eggs are not laid here by them.\n\nThe stream from the current carries their eggs to the dam, but whatever is laying them will be found upstream.\n\nGo northeast, to the river's main source, and deal with the root of the corruption.", sourceObjective = "Go to the northeastern source of the Vir'naal River and slay Scalemother Hevna.", completion = "Yes.  The waters are clearing up.\n\nI am certain I will be visited by a vision before the High Council meets.\n\nBe warned, {race}.  My vote will only be swayed by what I see.\n\nYou might have helped us greatly here today, but if the vision sways me to make a case against war then that is the way my vote will be cast.", sourceObjectiveStatus = "unverified-source-field" }
quests[27839] = { id = 27839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Weapons", description = "Though we aren't formally at war yet, the Neferset do not hesitate to imprison or kill all who trespass upon their territories.\n\nKing Phaoris refuses to reciprocate, even when they use our lands to smuggle stolen relics from the tombs of our ancestors.\n\nMy scouts report that the Neferset are about to move a major shipment of looted weapons south of here.\n\nI've instructed the laborers you recruited to assist you.  Call upon them with this horn when you find the smugglers and recover the weapons.", sourceObjective = "Retrieve the Ancient Tol'vir Armaments", progress = "You've returned, {name}.  How did the operation go?", completion = "This is quite timely.  I will distribute these armaments to my best men and to the laborers that you recruited.\n\nI've a feeling they'll show as much courage as my best trained captains.", sourceObjectiveStatus = "unverified-source-field" }
quests[27840] = { id = 27840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenethyst Crystals", description = "The lost ones who live in the Fallow Sanctuary look as we look, but they are monsters... driven mad by the rigors of our journey to Azeroth.  Once our brethren, they now live in the Fallow Sanctuary to the west, catching or killing any who wander near.\n\nAnd they have stolen something sacred to us--draenethyst crystals.\n\nWe lack the force to enter the Fallow Sanctuary and reclaim our stolen draenethyst from among their huts and campfires, but without those crystals... we too may lose our way.", sourceObjective = "Collect 5 Draenethyst Crystals from the Fallow Sanctuary.", progress = "Do you have the crystals?", completion = "Thank you, {name}.  We, are in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27841] = { id = 27841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", sourceObjective = "Acquire some Bread of the Dead and give it to the Cheerful Goblin Spirit in Orgrimmar's graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27842] = { id = 27842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only the Beginning", description = "I miss the days when legions of powerful ogres marched by the Horde's side into battle, the pathetic Alliance cowering at their ferocity. Perhaps those days will return before I am gone to the ancestors.\n\nHowever, that is not the case now. An ogre magi, Glubtok, has joined forces with the despicable Defias Brotherhood and acts as Foreman over their mining operations. The pathetic fool! End his life for me, and for the spirit and glory of the Horde!", sourceObjective = "Kill Glubtok.", completion = "Do not be alarmed, {name}. I am close to you, waiting in the shadows. You've done well.\n\nYou must continue the mission here - I am too valuable to risk my life against petty criminals like these.", sourceObjectiveStatus = "unverified-source-field" }
quests[27843] = { id = 27843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements Denied", description = "Just killing ogres won't be enough. The ogres themselves are being summoned onto the battlefield far too rapidly.\n\nI need you to go far behind the enemy line and seek out their summoners. The orcs are using warlocks to bring their reinforcements in.\n\nCut down the warlocks, and the portals should close. There aren't many of them; a quick, surgical strike should cripple the enemy.", sourceObjective = "Slay 3 Stonard Warlocks.", completion = "Once again, well done. With a few more pushes the battle will be ours.", sourceObjectiveStatus = "unverified-source-field" }
quests[27844] = { id = 27844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitors!!!", description = "The goblins you'll find working with the Defias are officially traitors to the Bilgewater Cartel, the Shattered Hand, and the Horde itself!\n\nI haven't yet been initiated into the Shattered Hand, so my loyalties lie strongly with my people. Helix Gearbreaker apparently has no time for such associations, and works on building a mast for the Defias Juggernaut. On behalf of Miss Mayhem and myself, would you kindly 'dispose' of Helix?", sourceObjective = "Defeat Helix Gearbreaker.", progress = "Yes?", completion = "My employers do not take kindly to traitors.\n\nOn the flip side, they are renown for their kindness towards the loyal! You deserve to be rewarded!", sourceObjectiveStatus = "unverified-source-field" }
quests[27845] = { id = 27845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marking the Fallen", description = "We've taken more than we've lost, but we've still lost too much. Too many brave have given their lives for the Alliance out there. I want to make sure they're given proper honors no matter how fierce this battle gets.\n\nTake these flags out with you and place one on any fallen soldier you see. The protective wards on them won't offer much protection against any defilement, but it's better than nothing. I'll be able to better judge how many we've lost from a distance, as well.", sourceObjective = "Use the Banner of the Fallen to mark 7 Fallen Marshtide Footmen.", completion = "Thank you, {name}. Those soldiers deserve better than to be left face down in the mud.", sourceObjectiveStatus = "unverified-source-field" }
quests[27846] = { id = 27846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", sourceObjective = "Acquire some Bread of the Dead and give it to the Cheerful Worgen Spirit in Darnassus' graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27847] = { id = 27847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Quite There", description = "These prototypes are going to change the face of Horde warfare when I perfect them! The issue I've been having is that their power sources don't allow for complicated combat maneuvers or large frames, both highly desired traits when it comes to fighting Alliance.\n\nThe Defias, with some help from goblin traitors like Helix, have almost completed the Foe Reaper 5000, a massive golem that will actually work!\n\nWe can't have that going public, can we? I'll lose customers!", sourceObjective = "Destroy the Foe Reaper 5000.", progress = "Yes?", completion = "Brilliant! Now all I have to do is finish my work, and my Mayhem Reapers will cause...mayhem...on any Horde front!\n\nAnd there won't be any Defias knockoffs to steal my profits!", sourceObjectiveStatus = "unverified-source-field" }
quests[27848] = { id = 27848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Intentions...Poor Execution", description = "The Defias plan to finish their Juggernaut and use it to lay waste to Stormwind. It is a noble cause any true orc warrior would embrace without a single thought!\n\nVanessa's fault lies in her execution of their plan. The ship is poorly constructed, the crew practically untrained, and, worst of all, there's a worgen in their midst!\n\nHis name is Admiral Ripsnarl, and he must be mercilessly slain in the name of the Warchief. Lok'tar ogar!", sourceObjective = "Kill Admiral Ripsnarl.", completion = "It's a shame that he was both a human and a worgen. Had he been a proud orc warrior I'd have liked to charge into battle alongside such a fierce combatant.\n\nWe can speak of ill-fated desires another day. It is time to take what is ours from the enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27849] = { id = 27849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Stonard", description = "This is it, {name}. We've made our final push into Stonard itself.\n\nI shouldn't have to remind anyone, but I'll say it anyway: We're not orcs, and we're not going to become them out of revenge or spite. Stonard will not be burned to the ground for us to dance on the ashes.\n\nNo, I want this done right. I want this surgical. Hold your head high and strike down any orc that picks up a weapon.", sourceObjective = "Slay 6 Stonard Defenders.", completion = "You've followed orders well, {name}. On behalf of the crown, I'm rewarding you for your bravery on the battlefield.", sourceObjectiveStatus = "unverified-source-field" }
quests[27850] = { id = 27850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defias Kingpin", description = "The Shattered Hand has laid mostly quiet for years now.\n\nNo more!\n\nYou will be the instrument of our rebirth, {name}. Slay the Defias Kingpin and commandeer her ship for the Horde! We will outfit it as a proper orc warship and use it to finally lay waste to Stormwind\n\nAny survivors will spread word of our unstoppable power across all of Azeroth, and all will tremble before our might!\n\nGo now, VanCleef's death will be your greatest triumph yet hero.", sourceObjective = "Kill the Defias Kingpin.", completion = "COWARD!!! Vanessa VanCleef is a dirty human coward! How dare she flee from battle against the Horde and leave her unworthy subordinate to fight!\n\n<Kagtha composes herself.>\n\nNo matter. Her ship is reward enough. The citizens of Stormwind will bear first hand witness to our awe inspiring power using a ship made in part by the very architect of their city!", sourceObjectiveStatus = "unverified-source-field" }
quests[27851] = { id = 27851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Supply", description = "We may not be flattening Stonard into dust, but I don't want to have to go in there a second time.\n\nI want you to gather any supplies you see in the town while you're there. Without food, they won't have any fighters after more than a day.\n\nThere should be crates scattered all over town.", sourceObjective = "Seize 5 crates of Stonard Supplies.", progress = "What's the situation?", completion = "Good work, {name}. With this, it's only a matter of time until the orcs are fleeing for the portal or begging for surrender.", sourceObjectiveStatus = "unverified-source-field" }
quests[27852] = { id = 27852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs and Humans", description = "War rages in the swamp, {name}. Vicious humans have settled north of the city and brought an army to our doorstep.\n\nThere is nothing in this swamp for them. Their sole reason for coming here is to attack us, unprovoked. We will not give them the pleasure of victory!\n\nWe are undermanned and I need every able orc to take to the battlefield. Go, and slay as many humans as you can.", sourceObjective = "Slay 10 Marshtide Footmen.", completion = "We will fight to the last orc, {name}. I hope you'll keep yourself alive long enough to properly destroy these trespassers.", sourceObjectiveStatus = "unverified-source-field" }
quests[27853] = { id = 27853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumbering Oafs", description = "We are outnumbered by the Alliance. In their fear they send an army to crush a single settlement. But we will not give!\n\nWithout resources, their soldiers will be at a disadvantage. Human peasants busy themselves in the woods outside Marshtide Watch, gathering lumber to rebuild their crumbling walls.\n\nDeny them the wood, and their lives.", sourceObjective = "Slay 5 Marshtide Peasants.", completion = "No true member of the Horde should find pleasure in killing such terrified weaklings... without challenge, victory has no true thrill.\n\nBut your dirty work has helped stave off the Alliance and protect our homes here. Be proud of your work for the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27854] = { id = 27854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tides of Darkness", description = "We have suffered many losses, {name}. Dreadmaul Hold has sent ogres from the Blasted Lands as reinforcements, but they can only send so many; the Alliance attacks them as well, even as we speak.\n\nThe Alliance has countered our ogres with mounted knights, a strategy that served them well in the Second War. We will need our strongest warriors to turn the tide of battle!\n\nReturn to the Bloodmire, {name}, and bring down those knights!", sourceObjective = "Slay 6 Marshtide Knights.", completion = "You are a true champion, {name}, to take the lives of so many on the battlefield. I hope it will be enough to save Stonard.", sourceObjectiveStatus = "unverified-source-field" }
quests[27855] = { id = 27855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements Denied", description = "The Alliance has brought in their mages to summon more reinforcements directly to the battlefield from beyond their fortress. This must be stopped!\n\nTheir numbers are few, but a single portal can turn the tide of battle. Attack their mages and shut off those portals!", sourceObjective = "Slay 3 Marshtide Mages.", completion = "With no link to the outside, the Alliance must rely on what they've brought to the swamp. We shall see if they can handle our home environment.", sourceObjectiveStatus = "unverified-source-field" }
quests[27856] = { id = 27856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marking the Fallen", description = "Many warriors have met death to bring us victory, {name}. The fate of a true orc.\n\nI have seen the way the Alliance loots the bodies of our fallen, clutching at our goods like packrats. They will not defile our fallen heroes on this field.\n\nTake these wards with you to the Bloodmire. Place them on the bodies of our fallen warriors. I will be watching, to see how many have fallen, and to honor their sacrifice. Let us hope the spirits give us aid for our respect.", sourceObjective = "Use the Banner of the Fallen to mark 7 Fallen Stonard Warriors.", completion = "You honor both the dead and the living with your courage, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27857] = { id = 27857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Under Attack!", description = "The Alliance are at our walls!\n\nYour actions delayed them and weakened their forces, {name}, but in the end we are outnumbered. This is our last stand. Victory or death...\n\nFight with honor, {name}. They are within the walls as we speak. Drive the human dogs from Stonard, for the Horde!", sourceObjective = "Slay 12 Marshtide Invaders.", progress = "There is no time! Go! Fight!", completion = "The Alliance is driven out! Stonard will be safe, thanks to your ferocity. Lok'tar Ogar!", sourceObjectiveStatus = "unverified-source-field" }
quests[27858] = { id = 27858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rheastrasza's Gift", description = "Wait here.  I will retrieve the egg.", sourceObjective = "Wait as Rhea retrieves the egg from the Hidden Clutch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27859] = { id = 27859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Egg Lives On", sourceObjective = "Wait as Rhea retrieves the egg from the Hidden Clutch.", completion = "You were not the only mortal that Rheastrasza confided in.  I too earned the dragon's trust.\n\nI have already moved the real purified egg on to a safer location, away from the Badlands.  It will continue to grow, out of Deathwing's sight.\n\nThe red dragonflight is as benevolent as it is powerful.  It was Rheastrasza's final wish that I give this to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27860] = { id = 27860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Ones", description = "When the Dark Portal closed many years ago, regret and fear seized many of us who had come to these lands. In their despair, they cursed the name of the Light, and sank into violence and hatred.\n\nThese fallen souls are now the Lost Ones, little more than mindless monsters, attacking all who approach. They grow more corrupt by the day, and as they die off, they have begun to kidnap from the Harborage..\n\nThey are beyond help, {name}. Their suffering must end. Will you put them from their misery?", sourceObjective = "Slay 12 Lost Ones in the Fallow Sanctuary.", completion = "It still pains my heart to have asked you to do this, though I know there is no other way. You have saved those of us still holding on from a terrible menace.", sourceObjectiveStatus = "unverified-source-field" }
quests[27861] = { id = 27861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "I was wondering when you'd show up, {name}! Having a past champion of the Ring of Blood here will be a huge draw! We're gonna be rich, buddy! RICH!\n\nAnyway, this is some old Dragonmaw fighting pit. Didn't take much modification to tune it up to our uses. I put out a few feelers, and got some heavy hitters from all around Azeroth to join in the carnage. Bout time to make some gold!\n\nYou know the drill, {name}. When you're ready, let me know and we'll get this show on the road!", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!", sourceObjectiveStatus = "unverified-source-field" }
quests[27862] = { id = 27862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "Well well, if it isn't the once champion of anguish, {name}! I'm seeing good money in the future now that you're here! We're gonna be rollin in the dough, buddy! Filthy RICH!\n\nAnyway, this is some old Dragonmaw fighting pit. Didn't take much modification to tune it up to our uses. I put out a few feelers, and got some heavy hitters from all around Azeroth to join in the carnage. Bout time to make some gold!\n\nYou know the drill, {name}. When you're ready, let me know and we'll get this show on the road!", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!", sourceObjectiveStatus = "unverified-source-field" }
quests[27863] = { id = 27863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand or the bloodbowl in Zul'Drak, but hey, I go where the gold's at! So welcome to Twi-Hi, pal.\n\nYou're new to this pit, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match.\n\nIf you're ready and got a group of friends with you, we can start! What do you say?", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!", progress = "No payout until the fight's over, man.", completion = "Not bad, friend. You might make some gold out here - if you manage to stay alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[27864] = { id = 27864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Deadly Dragonmaw!", description = "You're going to love this one! The Dragonmaw heard you were entering the arena and they're determined to make sure you don't leave it.\n\nTime for some good ol' {race} on orc action! Let me know when you're ready to do this!", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat Torg Drakeflayer!", completion = "No love in your heart for orcs I see. You really made a mess of that guy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27865] = { id = 27865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Wayward Wildhammer!", description = "You're going to love this one! The Wildhammer heard you were entering the arena and they're determined to make sure you don't leave it.\n\nTime for some good ol' {race} on dwarf action! Let me know when you're ready to do this!", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat Sully Kneecapper!", progress = "No payout until the fight's over, man.", completion = "No love in your heart for dwarves I see. You really made a mess of that guy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27866] = { id = 27866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: Calder's Creation!", description = "Grim and gory, this next match is sure to have the crowd groanin' one way or another. Calder Gray has been gathering the bodyparts of defeated challengers and building the perfect champion.\n\nThis thing is the ultimate cobbled collaboration of corpsified combatants. A magnificent mashup of mangled monstrosities. Are you ready to get messy?! Cause I am! Let me know when you're ready so we can get this thing started!", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat the Cadaver Collage!", progress = "No payout until the fight's over, man.", completion = "Wow! When I saw that... thing stumble into the arena, I thought you didn't stand a chance. But you proved me wrong. You tore it apart!\n\nGrizzly business.", sourceObjectiveStatus = "unverified-source-field" }
quests[27867] = { id = 27867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Earl of Evisceration!", description = "You're going to have your hands full with this one, pal. We've got a seasoned gentleman warrior here! He hails from Gilneas, and he's out to prove that he's the best warrior this side of Azeroth.\n\nYou better pull up those boots and zip up those pants, because it's going to get downright feral up in here. Give me the word when you're down for some punishment.", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat Lord Geoffery Tulvan!", progress = "No payout until the fight's over, man.", completion = "You really pulled that one out. I thought you were done for sure when he wolfed and started tearing up the arena. I guess I should know by now that you don't go down easy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27868] = { id = 27868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Twilight Terror!", description = "We've got someone you'll really love to hate this time around. I wasn't sure at first if I should let him into the pit, but a fight's a fight! And who am I to turn down some guaranteed cash?!\n\nThis guy hails from the Twilight Citadel itself, and comes toting a toasty punch. Better move fast and watch your back! Just give me the word when you're ready for some action.", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat Emberscar the Devourer!", progress = "No payout until the fight's over, man.", completion = "Looks like this title is yours! You really pulled that one out of the fire. \n\nCongratulations. I hope the coin serves you well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27869] = { id = 27869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dragon and the Temple", description = "These serpents must be from the Temple of Atal'Hakkar. I already had a hint...\n\nNot a few days ago, I had a visitor stop by and ask me to keep an eye out for such things. An elf by the name of Itharius. I'm sure he didn't think I could see through his form... he was a green dragon in disguise, come here to help his fallen brothers no doubt.\n\nHe may very well be on to something. Itharius left for the temple itself. Perhaps you'd better go look for him there. Dark things are afoot.", sourceObjective = "Speak with Lord Itharius atop the outer steps of the Temple of Atal'Hakkar.", completion = "The goblin sent you? She has a cunning eye, that one.\n\nShe speaks the truth. I am here to stem the tide of corruption seeping from this temple. If you would save your people from a wicked fate, {name}, I ask for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27870] = { id = 27870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Marshtide Watch", description = "Regardless of whether you assist me within the temple, your people must be told of what is brewing here.\n\nNorth of the temple, humans of your mortal Alliance have built what they call Marshtide Watch. They war with the Horde across the swamp, a raging conflict that I forsee only worsening.\n\nIt is not my role to interfere in mortal affairs, {name}. I simply ask you bring warning to your people of what lurks within the temple.", sourceObjective = "Speak with Joanna Blueheart at Marshtide Watch.", completion = "Trouble within the temple... I wish we could spare forces to deal with it. The war with Stonard is already raging, and we need every man we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[27871] = { id = 27871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Stonard", description = "Regardless of whether you assist me within the temple, your people must be told of what is brewing here.\n\nSouthwest of the temple is the Horde town of Stonard. The orcs there wage war with the new human arrivals to the swamp, a raging conflict that I forsee only worsening.\n\nIt is not my role to interfere in mortal affairs, {name}. I simply ask you bring warning to your people of what lurks within the temple.", sourceObjective = "Speak with Dispatch Commander Ruag at Stonard in Swamp of Sorrows.", completion = "We have no time to send orcs to the temple, {name}. The humans come, and they are many. Stonard must be defended!", sourceObjectiveStatus = "unverified-source-field" }
quests[27874] = { id = 27874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aviana's Legacy", description = "Your expertise is needed elsewhere, {name}.\n\nJust southwest of the World Tree you will find the Shrine of Aviana, home to the Druids of the Talon. Aviana, the matron of all winged creatures, gave her life for this world ten thousand years ago.\n\nI sense her shrine is being threatened, as are the druids who guard it. Seek out Choluna, one of the wisest of the winged druids, deep within the shrine.", sourceObjective = "Locate Choluna at the Shrine of Aviana in Mount Hyjal.", completion = "Ysera herself sent you to me? Oh! It's an honor to speak with a representative of the aspects.\n\nIt's true that our shrine is in jeopardy. The harpies we once sheltered in our boughs have suddenly turned against us.\n\nBut please, don't rejoin the fight until you are ready. Our shrine is no mere battleground. Use its peace and power to center yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[27875] = { id = 27875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prayerblossom", description = "I have worked for years to try to cure the affliction of the Broken. The foul energies that corrupted them did  more than twist their bodies; it took the comfort of the Light from them. They cannot feel its warmth.\n\nI cannot let Magtoor pass on in darkness, {name}. Before he worsened, I was studying prayerblossom, a flower that grows in the shifting mire. It grows hardy in even the darkest shade. I beg of you, gather these flowers for me, for Magtoor's sake.", sourceObjective = "Collect 10 sprigs of Prayerblossom from the Shifting Mire.", progress = "Have you brought the prayerblossom?", completion = "Prayerblossom has been used by the Broken as a remedy since they settled in this swamp. If it soothes the physical form, it might be used for more powerful healing...", sourceObjectiveStatus = "unverified-source-field" }
quests[27876] = { id = 27876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Mire", description = "The Shifting Mire takes its name from a unique phenomenon. By some force, the extremely fine silt will collect, and move on its own accord, travelling as if alive.\n\nI originally worried this was some corruptive force, but my studies have shown the opposite; whatever energy invigorates this soil is positive in nature. Perhaps such vibrant life can be imparted onto the Broken to reawaken what they once were.\n\nThe silt may not take kindly to being collected, {name}. But please, help gather it.", sourceObjective = "Collect 10 samples of Invigorated Silt from Shifting Mireglobs.", progress = "Did you get those samples?", completion = "It will have to be purified, but this will be most helpful. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27877] = { id = 27877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Morons' League", description = "I need your help in a little project I'm working on, {name}.  It falls into a realm I like to call \"defensive archaeology\".\n\nI like to bury non-magical items in conspicuous places to fool those Alliance idiots into thinking they've found something valuable.\n\nHmm... Dark Iron dwarves wander Hammertoe's Digsite and Angor Fortress, to the north.  Bring their heads back to me.  Yes, that's right, their heads.\n\nOnce the flesh is stripped, we can use those skulls to interfere with the dwarves' work.", sourceObjective = "Obtain 15 Dark Iron Heads.", progress = "<Lidia waits expectantly.>", completion = "Excellent!  We'll bury these immediately.  Those Explorers' League dimwits will never suspect us!", sourceObjectiveStatus = "unverified-source-field" }
quests[27878] = { id = 27878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forcible Acquisition", description = "I've got a little proposition for you, if you're interested.\n\nThe Dark Iron dwarves were here long before we arrived.  That means that, once these titan ruins opened up, the Dark Irons were the first ones in there, looting all the choice items.  I'll bet they've still got those treasures locked up inside Angor Fortress, northwest of here.\n\nI want you to find such a treasure... then steal it.", sourceObjective = "Search for treasure in the bottom floor of Angor Fortress.", progress = "Back so soon?", completion = "I knew it!  The High Examiner will be pleased to see this.\n\nNice work, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27879] = { id = 27879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival of the Fattest", description = "We're hard-up for supplies, stranger.  With the black dragons raining destruction on our hunting grounds, we have no way to get food.\n\nThe ogres to our south, however, have exactly what we need.  Within their grotto you should find plenty of meat and crafting supplies.\n\nThey may put up a fight.  Be on your guard.", sourceObjective = "Obtain 6 pieces of Dustbelcher Meat and 10 sheets of Dustbelcher Silk.", progress = "Welcome back.", completion = "I imagine those ogres weren't too much trouble for you.  Here - some coin for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[27880] = { id = 27880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Half-Ton Holdouts", description = "My grunts have got this dragon problem under control.  Besides, I can't have an upstart {class} like you barging in and ruining our battle plans.\n\nYou want work?  Fine, I'll give you work.  Investigate the ogre camp to our southwest.  From what I've heard, a small army of combatants seems to have appeared outside of their hovel.\n\nWe can't sit and wait for them to flank us, soldier... especially while we're already embroiled with black dragons.  Thin their ranks before they thin ours.", sourceObjective = "Slay 12 Dustbelcher Combatants. You may kill Dustbelcher Maulers or Dustbelcher Shaman.", completion = "You've got the hint of a hero in you, {race}.\n\nNow get out of my battlefield.", sourceObjectiveStatus = "unverified-source-field" }
quests[27881] = { id = 27881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodwatcher Point", description = "I've got an idea, but it's a bit of a long shot.  Thankfully, long shots happen to be a specialty of mine.\n\nNorth of here, the Reliquary has uncovered a new set of titan ruins beneath the sands.  If there's anything older and wiser than dragons, it's titans.  Heck, I've heard rumors that the titans CREATED the dragons.\n\nTalk to High Examiner Tae'thelan Bloodwatcher at their camp to the northeast.  He'll have more information than I do about these titans.\n\nWhat did I tell you?  It's a long shot.", sourceObjective = "Speak with High Examiner Tae'thelan Bloodwatcher at Bloodwatcher Point in the Badlands.", completion = "Titans?  You come to me, asking about titans?\n\nYou've come to the right place, as we're on the brink of discovering something big.  You will, however, need to earn your keep first.", sourceObjectiveStatus = "unverified-source-field" }
quests[27882] = { id = 27882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Not About History, It's About Power", description = "The Explorers' League may have a yeoman's knowledge of the actual act of digging.  What they lack, however, is the good sense to USE the artifacts that they dig up.  They stow their treasures in stagnant museums instead of using these items of power for their true purpose.\n\nThe dwarves are fools.  Fortunately, they die easily.\n\nYou'll find them digging into canyon walls north of here.  Take whatever you can out of their stubby-fingered hands, then return it to me.", sourceObjective = "Obtain a Broken Chalice, a Dusty Vase, an Earthen Hieroglyph, and a Trogg Tool.", progress = "You've returned with liberated artifacts, I presume?", completion = "Chalice... worthless.\n\nVase... counterfeit.\n\nHieroglyph... interesting, but rather common.\n\nWhat's this?  I've never seen trogg craftsmanship of this caliber!  You've stumbled upon something rare indeed, {name}.\n\nWe must not be so hasty as to overlook the troggs.  They may be simple, but they know things about the deep, hidden places of this world.\n\nYou've performed well enough.  Let's talk titans, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[27883] = { id = 27883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Pawn", description = "One of the few items of worth that we managed to loot from these ruins is this small jade statue.\n\nWe believe it to be a key of some sort, but we're unable to determine what it opens.  As such, it is useless to me.\n\nPerhaps you'll have some better luck with it.", sourceObjective = "Find a use for the Warden's Pawn within the Tomb of the Watchers in the Badlands.\n\nProvided item:", completion = "<The statue clicks into place on the large stone slab.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27884] = { id = 27884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sentinel's Pawn", description = "We found this small red statue on the corpse of one of those Explorers' League archaeologists.  Sadly, it wasn't us who killed him.  The local wildlife had already taken care of that.\n\nThe statue is well-crafted, but apparently bereft of magical power.  You may use it for whatever means you deem necessary.", sourceObjective = "Find a use for the Sentinel's Pawn within the Tomb of the Watchers in the Badlands.", completion = "<The statue slides into place on the cold marble slab.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27885] = { id = 27885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Game", description = "You see the statue split into two, then four, then eight identical statues in a square formation.\n\nYou hear a voice, not through your ears, but in the back of your mind:\n\n   \"A true warden does not face OUTWARD, searching for signs of danger.\n  A true warden keeps his gaze INWARD, always focused on protecting his quarry.\"\n\nPerhaps this is a riddle of some sort?", sourceObjective = "Complete the Warden's Game by teleporting the Warden's Pawns into inward-facing positions.", sourceObjectiveStatus = "unverified-source-field" }
quests[27886] = { id = 27886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sentinel's Game", description = "As you place the statue in its place, several other stone statues appear in the room.  One more ruby-colored statue also appears, in a small enclosure on the far end of the room.  You hear a voice:\n\n  \"The Sentinel watches.\n  The Sentinel protects.\n   The Sentinel's vision never falters.\"\n\nThat red statue on the other side of the room looks important.  Perhaps you should try to connect the two red statues?", sourceObjective = "Complete the Sentinel's Game by connecting the two red statues.", sourceObjectiveStatus = "unverified-source-field" }
quests[27887] = { id = 27887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Protectors", description = "You heard a good amount of rumbling happen in the tomb's central chamber.  Those two large statues did look awfully suspicious.", sourceObjective = "Investigate The Warden and The Sentinel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27888] = { id = 27888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Blam", description = "Inside the chest, you find a small, circular device, resting upon a cushion.\n\nIf there are any titan artifacts to be found here in the tomb, this is it.  You resolve to bring it back to Dr. Blam.", sourceObjective = "Bring the Eye of the Watchers to Dr. Hieronymus Blam at Agmond's End in the Badlands.", progress = "Well?  Has our long shot paid off?", completion = "Just one tiny little device?\n\nI never did understand those titans.\n\nVery well!  Let's see what this peeper can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[27889] = { id = 27889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Kargath", description = "<Dr. Blam stares at the egg in awed silence, blinks a few times, then looks up at you.>\n\nD... did you see that?  Incredible!  My titan thing idea worked!  With your help, of course.\n\nWe'll want to get these back to Rhea.  She's not at Lethlor Ravine anymore; it sounds like she blew her cover when she transformed into her true form in front of all those whelps.  She's now in the west, staying at a large Horde establishment dubbed \"New Kargath\".\n\nShe'll be waiting for you.  And for that egg.", sourceObjective = "Bring the Purified Black Dragon Egg to Rhea at New Kargath in the Badlands.", progress = "That's some precious cargo you carry there, {name}.", completion = "I'll take that egg out of your hands now.  We need to get this egg incubated... and hidden, quickly.  There are lots of angry dragons looking for this.\n\nIt's good to see you again, by the way.", sourceObjectiveStatus = "unverified-source-field" }
quests[27890] = { id = 27890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bad Dogs", description = "In my haste to escape from Lethlor Ravine, I forgot to tie up one loose end: Nyxondra.  She's free, and she's sounded the alarm among the black dragonflight.  Half the flight is here in the western Badlands, combing for this egg.\n\nI'll take care of hiding the egg.  You're going to take care of some of the more troublesome dragons.  And you'll have help.\n\nI've paid off a couple of mercenaries to help you.  You'll find them inside this inn.", sourceObjective = "Speak with Amakkar at New Kargath in the Badlands.", completion = "You're the {race} we've been waiting for?  It's about time you got here.  My legs could use a stretch.\n\nCome on boys!  Let's go kill us some black dragons!", sourceObjectiveStatus = "unverified-source-field" }
quests[27891] = { id = 27891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amakkar, Jack of All Trades", description = "Before we get too crazy with the dragon-killing, let me tell you a little bit about how I fight.\n\nI'm not terribly strong or stalwart like these other two, but I've got a few tricks.  At your command I'll stun your enemies to keep 'em held still.  I also make sure to keep a few potions around for tight spots.\n\nWhy don't we practice fighting together?  Head out into the field, and you can see what it's like to fight with a real orc.", sourceObjective = "Use Amakkar's Kidney Shot and Amakkar's Pocket Potion.", progress = "We're not through yet, {name}.", completion = "I'm looking forward to fighting with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27892] = { id = 27892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jurrix the Striker", description = "Oh, you want to talk?  Fine.\n\nI'm Jurrix, the only merc here with half a brain.  The only one with any bite to my attacks, too.  The only reason I keep these meat shields around is to keep myself from getting killed.\n\nListen, you're the boss of this operation.  You give the word, and I'll send a fireball right through your target's heart.  If things start getting hectic, I can even warp time a bit so you can fit in a few extra attacks.\n\nWhy don't we go try fighting together?", sourceObjective = "Use Jurrix's Fiery Blast and Jurrix's Time Warp.", completion = "I think you're ready, {name}.  You're getting the hang of this.", sourceObjectiveStatus = "unverified-source-field" }
quests[27893] = { id = 27893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gargal, the Behemoth", description = "You may not have noticed, but I'm pretty big, as far as orcs go.\n\nI make sure that my two pals here don't get into too much trouble.  They're small, and they don't have a big shield like me.  I'm big, and I can handle a few monsters hitting me!  Plus, if I'm careful, I can usually get them to hit my shield instead!\n\nI can protect you, too.  Come on, let's go practice for a bit.  I'll make sure the enemies attack me, and not you.", sourceObjective = "Use Gargal's Shield Wall and Gargal's Mighty Shout.", progress = "Don't worry, little {race}.  I'll protect you.", completion = "See?  No need to worry when Gargal is around.  Just let me know, and I'll protect you from the monsters.", sourceObjectiveStatus = "unverified-source-field" }
quests[27894] = { id = 27894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrath of a Dragonflight", description = "Hello, {name}.  It looks like you four have had time to become well-acquainted.\n\nI have my first assignment for you.  Kalaran, an ancient black dragon of considerable power, has joined in the hunt for the egg we are protecting.  We need to stop him before he gets too close.\n\nYou will find him and his minions at the Dustbowl, east of New Kargath.  Hunt him down and defeat him.  You will likely need the help of your new mercenary allies.", sourceObjective = "Slay Kalaran the Annihilator and 4 Darkflight Soldiers.", sourceObjectiveStatus = "unverified-source-field" }
quests[27895] = { id = 27895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Their Hunt Continues", description = "The black dragonflight means business.  As you've probably already noticed, they've taken over a large portion of New Kargath.  These troops are under the command of General Jirakka and his champion, Moldarr.  They must be stopped.", sourceObjective = "Defeat General Jirakka, Moldarr, and 6 Blackflight dragonspawn.", sourceObjectiveStatus = "unverified-source-field" }
quests[27896] = { id = 27896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sorrow and the Fury", description = "My greatest regret is the treatment that we - no, I - gave to Nyxondra.  I forced her to lay eggs, then I performed experiments on them.  Over, and over, and over again.\n\nEven as a mother myself, I can only imagine her sorrow.\n\nNo... I mustn't be weak.  Our work is, after all, for the benefit of future generations of black dragons.  Her sacrifice was necessary.\n\nShe circles the Ruins of Kargath, northwest of New Kargath, insane with fury.  Please, heroes... put her out of her misery.", sourceObjective = "Slay Nyxondra and 12 of Nyxondra's Broodlings.", sourceObjectiveStatus = "unverified-source-field" }
quests[27897] = { id = 27897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Clutch", description = "With the major black dragons out of the Badlands, it is now safe to move the egg again.  You will find me on a small plateau, north of New Kargath.\n\nCome and find me.", sourceObjective = "Speak with Rhea at The Hidden Clutch in the Badlands.", completion = "The egg must always be moving.  We are not safe anywhere.\n\nDeathwing, even in his madness, knows all the hidden places in this world.  The egg must not rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[27898] = { id = 27898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rheastrasza's Gift", description = "Wait here.  I will retrieve the egg.", sourceObjective = "Wait as Rhea retrieves the egg from the Hidden Clutch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27899] = { id = 27899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Gleam in his Eye", description = "If you're looking for Harrison, you just missed him.\n\nHe was going on and on about his latest discovery, and how everything was beginning to make sense.\n\nWhatever... he certainly wasn't making sense to me.\n\nI tried to convince him to stay here and just enjoy a few desert sunsets with me, but there's no talking to him when he gets that gleam in his eye.\n\nPerhaps you'd be willing to check in on him?\n\nHe was headed to that big monolith, south of here.", sourceObjective = "Speak to Harrison Jones at the Obelisk of the Sun.", completion = "It would seem that I'm not the only one interested in these obelisks...", sourceObjectiveStatus = "unverified-source-field" }
quests[27900] = { id = 27900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I've Got This Guy", description = "Good timing, {name}.\n\nSeems I'm not the only one interested in these obelisks, and these fellas aren't inclined to compare notes...\n\nI think I can handle this guy.\n\nMaybe you could take care of a few of his friends before they make their way over here?", sourceObjective = "Kill 10 Schnottz Air Troopers.", progress = "This guy's tougher than he looks - and he looks tough!", completion = "That's a relief. Thanks, {name}.\n\nTurns out I've got my hands full here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27901] = { id = 27901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Don't Know What They've Got Here", description = "Listen, {name}. I don't have a lot of time to talk here.\n\nThese guys are excavating relics from this site and taking pieces of ancient technology that we need!\n\nI need you to check their crates for pieces of an ancient activation device. The officers should have the codes you'll need to open them.\n\nHurry!\n\nWe can't let them load this stuff into their planes!", sourceObjective = "Create the Titan Activation Device.", progress = "Have you got the titan activation device, {name}?", completion = "That's it!\n\nGood work, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27902] = { id = 27902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purespring", description = "Magtoor has told me of the shamanism that the Broken practice. The great Nobundo once said that the path of the elements may, in a way, be another way to the Light.\n\nI can only hope there is some truth in this. The elementals that gather near Purespring Cavern to the south are a source of truly pristine water. They can be chaotic and violent, but the pure water harvested from them will be the perfect conduit for the blessing of the Light.\n\nPlease, bring me this water, {name}.", sourceObjective = "Collect 6 Purespring Motes from Purespring Elementals.", progress = "Have the elements given up their source?", completion = "Such clarity... let us hope this will aid poor Magtoor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27903] = { id = 27903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ignition", description = "This guy just won't go down!\n\nYou're doin' great, kid. Only one thing left to do.\n\nAccording to my research, there should be a titan statue down below. Use the device to activate it, then break it down.\n\nIf my theory is correct, that statue holds the key to reactivating this obelisk.", sourceObjective = "Recover the Lens of the Sun.", progress = "Time to see if this old mechanism still works...", completion = "According to Harrison's notes, placing the lens upon this dais should re-activate this obelisk.\n\nExactly what that means remains to be seen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27904] = { id = 27904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breath of Mist", description = "The Grell are forest spirits that wander the Misty Valley to the east. Though they resemble imps, I have found no demonic traces among the ones I've studied. They are, as far as I can tell, uncorrupted. \n\nThose that dwell in the valley move as one with the wind, summoning gusts of breeze at their whim. This pure air may be incorporated into my remedy for poor Magtoor.\n\nPlease, {name}, gather the smoky crystals found within the grells' bodies for me. I must exhaust every potential cure.", sourceObjective = "Collect 5 Smoky Crystals from Misty Grell.", progress = "Do you have the crystals?", completion = "I can only hope this will lead to a cure, {name}. Thank you for bringing it to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[27905] = { id = 27905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tailgunner!", description = "Okay, I've softened this guy up, how about you help me finish him off?\n\nI've got a plan for our escape, but it'll require a lot of guts and a little luck.\n\nYou up for it, {name}?\n\nJust follow my lead...", sourceObjective = "Use the tailgun to defend the Schnottz Bomber.", completion = "Good work back there, {name}.\n\nLooks like we've lost them, for now at least.", sourceObjectiveStatus = "unverified-source-field" }
quests[27906] = { id = 27906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neeka Bloodscar", description = "There is much work to do in recovering from the assault and bracing ourselves for the next one. I will need coordination from all of our scouts.\n\nNeeka Bloodscar is our finest tracker, trained in the harsh Badlands. She has been sent west to Splinterspear Junction to watch for Alliance activity.\n\nGo to Neeka, {name}. Tell her of what has occured in Stonard. Assist her in any way she requires.", sourceObjective = "Speak with Neeka Bloodscar at Splinterspear Junction.", completion = "I hope the sight of my sniveling amuses you, {name}. It will be the only joy here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27907] = { id = 27907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prayerblossom", description = "I have been ruined, {class}. I placed my strength in Helgrum, and now it bleeds from his gaping wounds. Wounds too deep to heal, flesh that refuses to knit.\n\nHe murmurs in fear, consumed by fever and pain. I cannot leave his side. Not now. Please, I ask you in shame to gather herbs for me.\n\nThe prayerblossom that grows in the swamp is an old remedy for soothing. With enough of it, his pain might be stilled.", sourceObjective = "Collect 10 sprigs of Prayerblossom from the Shifting Mire.", progress = "Have you brought the prayerblossom?", completion = "I will grind these and try to get him to eat. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27908] = { id = 27908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Mire", description = "Helgrum's wounds fester in the swamp air. They swell and ooze, filling his final moments with suffering. I must have something to coat them with.\n\nThe spirits move through this mire. They inhabit the mud itself, pushing it along in clumps of fine soil that take on lives of their own\n\nThe spirits of the cool, pure mud will offer him some comfort. Please, gather it for me, for I cannot abandon his side.", sourceObjective = "Collect 10 samples of Invigorated Silt from Shifting Mireglobs.", progress = "Helgrum still breathes. Do you have the mud?", completion = "At least I can soothe him with my own hands while he still breathes. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27909] = { id = 27909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purespring", description = "Helgrum's breathing slows. His time is near.\n\nI need water. Elementals roam the ponds of Purespring Cavern. The water that flows from them is the purest in this swamp.\n\nEven if I could risk leaving Helgrum's side, my axe would shudder in my hand. I must beg you once again to pity me, for his comfort. Bring me the motes of the elementals, that his final drink may be pure and refreshing.", sourceObjective = "Collect 8 Purespring Motes from Purespring Elementals.", progress = "You've returned.", completion = "He can only drink so much. The rest might be used for washing his body, after...\n\n<Neeka glares in frustration and shudders, turning her head away.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27910] = { id = 27910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Regrets", description = "If I am reduced to groveling, I may as well ask everything I can. There is one last favor I would ask of you, one more task a shamed orc pleads for.\n\nHelgrum had a prized prey. Duskfang, eater of ogres, the great panther of Misty Valley. He would never allow himself the leisure of stalking it. Though he wanted badly to hunt, our scouting duties were too important.\n\nIf he cannot hunt Duskfang in this world, he can hunt the beast in the next. Take up the hunt for him; bring Duskfang's pelt to me.", sourceObjective = "Collect Duskfang's Hide.", progress = "Has Duskfang shown himself?", completion = "With Duskfang to shroud his body, he will carry the animal's spirit with him into the afterlife.\n\nListen to me. An old superstitious fool. I'm so sorry, Helgrum...", sourceObjectiveStatus = "unverified-source-field" }
quests[27911] = { id = 27911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With Dying Breath", description = "He stirs...\n\nDo not leave, {name}. Please, honor Helgrum with me. You have done so much for him.", sourceObjective = "Witness Helgrum's last moments.", completion = "He is gone.\n\nHe is right. I must be strong for him...", sourceObjectiveStatus = "unverified-source-field" }
quests[27912] = { id = 27912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Titans' Trove", description = "As the second defender falls to the ground, a chest appears in the back of the chamber.  Could this be what they were protecting?", sourceObjective = "Investigate the Trove of the Watchers.", completion = "You peer into the chest...", sourceObjectiveStatus = "unverified-source-field" }
quests[27913] = { id = 27913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Titans' Trove", description = "As the second defender falls to the ground, a chest appears in the back of the chamber.  Could this be what they were protecting?", sourceObjective = "Investigate the Trove of the Watchers.", completion = "You peer into the chest...", sourceObjectiveStatus = "unverified-source-field" }
quests[27914] = { id = 27914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of the Green Dragonflight", description = "You have done well, {name}. Jammal'an may have escaped our grasp, but his retreat paves the way for me to enter the temple as I desire.\n\nStay where you are and do not move. I will hasten your return by pulling your spirit to me through the Emerald Dream.\n\nThis may cause slight drowsiness.", sourceObjective = "Speak with Lord Itharius atop the Temple of Atal'Hakkar.", completion = "You have performed a great service for me and my kind, {name}. Accept this as a symbol of my gratitude, and of your courage.", sourceObjectiveStatus = "unverified-source-field" }
quests[27915] = { id = 27915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Temple", description = "I must confess I have a more personal involvement in this affair. One of the first of the green dragons corrupted here was my brother, Eranikus.\n\nI thought Eranikus gone, lost forever to the darkest rifts of nightmare, but I have heard that his shade has emerged within the temple. I know not whether it is truly him, or an empty, mournful echo.\n\nIf you wish to help me further, return to the Hall of Masks and journey through the archway into the true sanctum of the temple. I will find you there.", sourceObjective = "Speak with Lord Itharius again inside the Temple of Atal'Hakkar.", completion = "I am pleased to see you once again, {name}. You are truly noble to assist me further.", sourceObjectiveStatus = "unverified-source-field" }
quests[27916] = { id = 27916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruag's Report", description = "Here is Ruag's report, {name}. Let him know his scout is still here.\n\nDo not speak of Helgrum. I will not distract others with news of tragedy.\n\nI have to be strong. We all have to be strong.", sourceObjective = "Deliver the Splinterspear Report to Dispatch Commander Ruag in Stonard.", progress = "Yes?", completion = "<Ruag reads over the report.>\n\nI see.  Thank you for this information, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27917] = { id = 27917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sniffing Them Out", description = "I could smell Godfrey and his companions a mile away from here. They did an exceedingly poor job covering their tracks in flight. It will be the mistake that puts the final nail in their coffins.\n\nOne of them is very close, and though the scent has changed slightly in undeath, I'm fairly certain it's Ashbury's. Go inside and tear him to pieces, we'll ensure the Forsaken do not intervene with our task.", sourceObjective = "Kill Baron Ashbury.", completion = "The scent of freshly spilled traitor blood fills my nostrils, and it is absolutely invigorating. However, my bloodlust will not be sated until Godfrey lies on the floor as a lifeless heap.\n\nHe thinks an army of mindless corpses can stop the wrath of the Bloodfang? We'll gnaw on their bones for years to come after our work is done!", sourceObjectiveStatus = "unverified-source-field" }
quests[27918] = { id = 27918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Harborage", description = "Anchorite Avuun is one of our uncorrupted bretheren, what other races know as Draenei. He came to The Harborage to heal us, and try to find a cure. It is he who sent me here to collect these crystals.\n\nHe watches over a very sick friend now... and despite sending word to the Exodar itself, he has not found any aid so far. Could you bring these crystals to him, {name}? You may be the only one able to assist him.", sourceObjective = "Deliver the Draenethyst Crystals to Anchorite Avuun.\n\nProvided item:", completion = "Thank you, {class}. I am afraid it may be too late... but I refuse to give up, even if the Exodar itself does not hear my cries.", sourceObjectiveStatus = "unverified-source-field" }
quests[27919] = { id = 27919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onward to the Blasted Lands", description = "We appreciate your assistance here in this swamp, {name}.  I would like to inform you that I have received correspondence from Nethergarde Keep.\n\nEnohar Thunderbrew has requested help in investigating the shipwrecks of the Red Reaches, but we have had none willing to make the journey, and I could not leave the Harborage.\n\nNethergarde Keep sits in the Blasted Lands, south of the Swamp of Sorrows.  Do not journey too close to Stonard on your way.", sourceObjective = "Journey to the Blasted Lands and speak with Enohar Thunderbrew in Nethergarde Keep.", completion = "Ah, has Avuun sent ye? Good, good...", sourceObjectiveStatus = "unverified-source-field" }
quests[27920] = { id = 27920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armored to the Teeth", description = "We've hit an unexpected snag in our assault on the keep, {name}. It seems the servants that tended to Baron Silverlaine and Commander Springvale in life do so now in death as well, and Godfrey has placed them directly between us and him.\n\nNot to worry, we won't let them be anything more than a minor inconvenience. Eliminate Silverlaine and Springvale both and not only will their guards no longer have masters to direct them, it will place us that much closer to our final goal.", sourceObjective = "Kill Baron Silverlaine and Commander Springvale.", progress = "It is infuriating that we have to kill these ghost soldiers when they are completely outside the main objective, but it must be done. Godfrey is a cunning foe indeed.", completion = "We're nearly there, {name}. The time is now to charge further ahead and take out Walden!", sourceObjectiveStatus = "unverified-source-field" }
quests[27921] = { id = 27921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting Tooth and Claw", description = "It appears that Lord Walden has finally taken notice to our presence and has heightened his defenses. It's worthless really... nothing will deter our pack.\n\nThe path ahead to him is rife with powerful Scourge minions, but I trust that you will be able to clear the path for the rest of us to follow in. Once we kill Walden, it should be a straight shot to his cowardly leader.", sourceObjective = "Kill Lord Walden.", progress = "We're behind you, {name}.", completion = "<Packleader Ivar Bloodfang grins, revealing his razor-sharp teeth.>\n\nIt won't be long now before the entire keep is ours, thanks to your valiant efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[27922] = { id = 27922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitors!", description = "Please, stranger.  You must help me.\n\nI came here to investigate the arrival of a powerful ally to the Neferset, only to be betrayed by my closest allies and given up to the enemy.\n\nGo to the terrace above us to the east and find the information I failed to uncover.  You'll need to hide from the Neferset.  Perhaps you can hide behind one of the large plants on the platform to conceal your presence.\n\nDo this for me and I will help your friends find their way to safety.", sourceObjective = "Hide behind the Neferset Frond and Uncover the Neferset Secret.", progress = "What did you witness, {name}?", completion = "A djinn!  We must escape as soon as possible.\n\nThis unholy alliance of the Neferset with the minions of Deathwing does not bode well for us.", sourceObjectiveStatus = "unverified-source-field" }
quests[27923] = { id = 27923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke in Their Eyes", description = "I'm not sure what knuckle-headed plan your friend is concocting, but we're going to need a distraction if we're to stand a chance of escaping.\n\nTake the torch from that brazier and go start some fires.\n\nPerhaps if we divert the Neferset scum's attention away for a few minutes, we'll have the opportunity we need.", sourceObjective = "Burn Stacks of Hay inside the Lost City of the Tol'vir in Uldum.", completion = "Yes.  I hear the Neferset calling each other to the east.  This might yet work.", sourceObjectiveStatus = "unverified-source-field" }
quests[27924] = { id = 27924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Budd's Plan", description = "I've an idea!  Trust me, it's a good one this time!\n\nGet some of those shiny armor pieces the cat-people wear.\n\nThis plan cannot fail.  Trust me.", sourceObjective = "Obtain 6 pieces of Neferset Armor.", progress = "Did you get the pieces, {name}?", completion = "Excellent.  You'll see, this can't possibly go wrong!", sourceObjectiveStatus = "unverified-source-field" }
quests[27925] = { id = 27925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Efficient Excavations", description = "This manual describes outlandish theories on how to efficiently manage large groups of workers as they engage in the manual labor of various types of excavation.\n\nIt becomes clear to you that the author of the book is the figure in charge of the over-aggressive pillagers here.\n\nPerhaps an introduction is in order.", sourceObjective = "Bring 'Efficient Excavations' to Belloc Brightblade in Schnottz's Landing.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[27926] = { id = 27926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eastern Hospitality", description = "The commander is quite busy now, I'm afraid.\n\nThe demands of an operation such as this require much of his attention these days.\n\nWhile you wait to speak with him, why don't you mingle with some of our guests?\n\nWe have invited a variety of Azeroth's most illustrious figures to be present when we unlock the secrets of this region.\n\nI am confident that you will find them most captivating.", sourceObjective = "Belloc Brightblade wants you to mingle with the guests at Schnottz's Landing.", progress = "Well, hello again, {class}.", completion = "I trust that you had no troubles fitting in with our guests, hmm?", sourceObjectiveStatus = "unverified-source-field" }
quests[27927] = { id = 27927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down to the Scar", description = "The Badlands are home to some unusual people, many of whom have been here for quite a long time.\n\nFor example, there were three gentlemen who were staying here in town.  I forget their names... the dwarf was Theldurin, I think?  Anyhow, they headed south with a pack full of ale a couple of days ago, and haven't been heard from since.  I think they were headed to that big scar.\n\nWould you mind checking in on them?  I'd like to make sure that they're alright.", sourceObjective = "Find Theldurin the Lost at the Scar of the Worldbreaker in the Badlands.", completion = "They sent you to check up on us?  Pshh... I've been around this desert longer than any of those chumps.  We're just soaking in some of the scenery and telling stories about old times.\n\nYou like telling stories?", sourceObjectiveStatus = "unverified-source-field" }
quests[27928] = { id = 27928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Favor for the Furrier", description = "The commander can be most generous to those who demonstrate their loyalty, and I know of something that you can do to curry favor with him.\n\nBefore building up his... ehh... workforce, he dealt in the furs of animals.\n\nHe is quite skilled in the art of leatherworking. The furrier can do wonders with even the most tattered pelts.\n\nThe dried oasis to the east is said to be home to a rare breed of coyote.\n\nTheir furs would make a very thoughtful gift.", sourceObjective = "Collect 5 Desert Coyote Pelts.", progress = "Were you successful in your hunt?", completion = "Oh, these are exquisite!\n\nThe commander will be able to make a winter uniform with these.", sourceObjectiveStatus = "unverified-source-field" }
quests[27929] = { id = 27929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag 'em Down", description = "A single Dragonmaw drake is worth a dozen Wildhammer gryphon-riders. Take them off of their lice-ridden birds and they're nothing.\n\nEven you can slay them easily, Horde-{class}.\n\nHunt gryphon riders flying over the river north of Bloodgulch. Take this hook and fling it at them as they fly by. Their momentum will hurl them from their mount, right to your feet. Finish them! Kill a few Thundermar gryphon riders and I'll believe your Horde is as mighty as you say.", sourceObjective = "Use the Barbed Fleshhook to dismount and kill 4 Thundermar Gryphon Riders.", completion = "You look a little battered. Those dwarves didn't give you any challenge, did they?\n\nStill, that was an impressive show.", sourceObjectiveStatus = "unverified-source-field" }
quests[27930] = { id = 27930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devastation", description = "The coast is clear.  If Rheastrasza or the egg were able to miraculously evade Deathwing's flames, they would probably need your assistance as soon as possible.", sourceObjective = "Search for Rheastrasza.", completion = "Heroes:\n\nIf you are reading this, then my suspicions were correct.  Deathwing has found us.  The egg is destroyed, as am I.\n\nThis was, actually, the plan from the beginning.  You see... the egg that Deathwing destroyed was not the egg he sought.\n\nIt was mine.", sourceObjectiveStatus = "unverified-source-field" }
quests[27931] = { id = 27931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Quaking Fields", description = "Before you can help us here, you're going have to deal with Therazane, the Stone Mother's, forces to the south. The elementals and giants upon the Quaking Fields are being mustered.\n\nThey too are after the middle fragment of the World Pillar. They'll attack us amidst our war with the stone troggs and we'll be unable to repel them.\n\nI've sent the arch geomancer ahead. Get to Slate Quicksand and do as he asks.", sourceObjective = "Speak with Slate Quicksand at the Quaking Fields in Deepholm.", completion = "Good, {race}, you're here.\n\nWe'll have to act fast if we're to prevent Therazane's forces from attacking.", sourceObjectiveStatus = "unverified-source-field" }
quests[27932] = { id = 27932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Axe of Earthly Sundering", description = "The emerald colossi are the greatest of the Stone Mother's creatures. They must be the first to be removed from the field.\n\nI brought Stonefather Oremantle's axe for just this task. Use it to sunder the giants.\n\nThat should bring them down to a more manageable size for you to finish off.", sourceObjective = "Slay 5 Sundered Emerald Colossi.", progress = "We need more of those giants destroyed, {name}.", completion = "Thank you, {name}. Without all of their giants, Therazane's forces will have a harder time taking Stonehearth.\n\nNow, if you please, hand back the axe. I'll keep it safe until you can rescue the Stonefather.", sourceObjectiveStatus = "unverified-source-field" }
quests[27933] = { id = 27933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Ore", description = "You're going to have to deal with the leader of Therazane's forces here. However, to get you to him quickly and safely, I'm going to need to perform a ritual.\n\nGo out into the field and collect elemental ore from the ragers. With enough of it, I should be able to make you one with the ground to get you where you need to go.", sourceObjective = "Collect 6 Elemental Ore.", progress = "Have you all that is required?", completion = "These should do. I'll just need a moment to prepare the ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[27934] = { id = 27934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One With the Ground", description = "The leader of the Stone Mother's forces here is the great earth elemental lord, Avalanchion. Luckily for us, the Twilight's Hammer cultists have decided to invade his lair. They're seeking to bind his elementals to their will.\n\nWe will take advantage of the chaos. The earth ritual that I invoke will make you one with the ground. It will take you near to Avalanchion without alerting him to your presence.\n\nIt's up to you to finish him.", sourceObjective = "Complete the One With the Ground ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[27935] = { id = 27935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down the Avalanche", description = "Avalanchion stands before you. Slay him to keep Therazane's forces from attacking Stonehearth.", sourceObjective = "Slay Avalanchion.", completion = "You've done what few others could have. Defeating Avalanchion was no small feat.\n\nI'm impressed, {name}. Will you help us with our war against the stone troggs so that we can rescue the Stonefather?", sourceObjectiveStatus = "unverified-source-field" }
quests[27936] = { id = 27936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down the Avalanche", description = "You have to go back and slay Avalanchion to keep Therazane's forces from attacking Stonehearth!", sourceObjective = "Slay Avalanchion.", completion = "You've done what few others could have. Defeating Avalanchion was no small feat.\n\nI'm impressed, {name}. Will you help us with our war against the stone troggs so that we can rescue the Stonefather?", sourceObjectiveStatus = "unverified-source-field" }
quests[27937] = { id = 27937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hero Returns", description = "The Stonefather is waiting for you back south at Stonehearth.\n\nMake yourself presentable. You've earned a hero's welcome!", sourceObjective = "Present yourself to Stonefather Oremantle at Stonehearth in Deepholm.", completion = "Our hero returns!\n\nYou have saved my people, {name}. You have earned that which you seek.", sourceObjectiveStatus = "unverified-source-field" }
quests[27938] = { id = 27938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Middle Fragment", description = "I present you with the key to Stonehearth. With it you may unlock the vault to my home and recover the middle fragment of the World Pillar.\n\nKeep the fragment safe, {name}. Make certain to get it to the Temple of Earth in the middle of Deepholm as quickly as possible!\n\nKnow that you are always welcome here.", sourceObjective = "Recover the Middle Fragment of the World Pillar.", progress = "You've returned. Did you recover the middle fragment?", completion = "The Middle Fragment of the World Pillar!\n\nThank you, {name}. I can only imagine what you had to go through to get this to us. I'll see to it that it's placed within the center of the chamber.", sourceObjectiveStatus = "unverified-source-field" }
quests[27939] = { id = 27939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Desert Fox", description = "Zhere is much to be done in zhis region, {race}.\n\nVe bozh haf a burning passion for zhe ancient technologies here, do ve not?\n\nPerhaps zhere is a vay for us to vork togezher?\n\nLet us put zhe misunderstandinks of zhe past behind us zhen, hmm?\n\nNow, zhere is an elusive animal in zhe region to zhe east zhat I have been huntink. Brink me zhis creature as a token of your sincerity, hmm?\n\nZhen maybe I let you in on my operation...", sourceObjective = "Schnottz wants you to bring him the Desert Fox.", progress = "Have you captured zhe Desert Fox, {class}?", completion = "You've done it!\n\nPerhaps I can trust you vizh more serious matters, hmm?", sourceObjectiveStatus = "unverified-source-field" }
quests[27940] = { id = 27940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirty Birds", description = "The sky above the Shriveled Oasis is littered with these nasty vultures.\n\nLike infectious rodents with wings, these creatures serve no great purpose and inflict untold misery.\n\nRid the skies of this nuisance and leave the region better than you found it.", sourceObjective = "You are to slay 8 Diseased Vultures.", sourceObjectiveStatus = "unverified-source-field" }
quests[27941] = { id = 27941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fashionism", description = "We have a strict policy among our ranks, one that we take most seriously.\n\nOur troops are to dress in official uniform at all times. This helps with organization, friendly fire incidents are reduced, and it keeps the troops looking wonderful!\n\nWe call it, Fashionism.\n\nWe've been running low on uniforms lately. I must ask that you recover them from the troopers that have fallen in the line of duty.\n\nYou should find plenty of the poor fellows east of here, at the Ruins of Ammon.", sourceObjective = "Belloc Brightblade wants you to collect 10 Trooper Uniforms.", progress = "Were you able to recover the uniforms we need?", completion = "Most efficient work, {class}.\n\nYou should rise rapidly through the ranks.", sourceObjectiveStatus = "unverified-source-field" }
quests[27942] = { id = 27942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Idolatry", description = "Zhere is somezhink I need handled, {race}.\n\nMy most trusted advisor has run afoul of an ancient curse. A hex zhat has transformed zhe man into a turkey, of all zhings!\n\nI haff studied for days to discover a remedy for his condition, and finally I am ready to conduct zhe ritual.\n\nI vill reqvire several idols from zhe nearby ruins. You are to brink zhem to me at vonce!\n\nDismissed!", sourceObjective = "Commander Schnottz wants you to collect 8 Well-preserved Idols.", progress = "Haff you brought me zhe idols, {race}?", completion = "Zhese look to be of sufficient quality.\n\nVizh zhese, ve are vone shtep closah to zhe cleansink ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[27943] = { id = 27943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angered Spirits", description = "Doctor Venkman vas vone of my greatest researchers, until he had to be put out of my misery.\n\nHe did leave me vizh vone of his greatest accomplishments, zhough. Against zhe properly attuned supernatural adversary, zhis veapon vill siphon zhe target's essence.\n\nIt is of key importance in zhe ritual I vill be attemptink.\n\nVhere do you come in, you ask? Simple. You have zhe priviledge of collecting zhe material.\n\nZhe veapon is calibrated to vork on zhe Furious Specters in zhe temple to zhe east.", sourceObjective = "Commander Schnottz wants you to use the L.P.A.C. to collect 5 Furious Spectral Essences.", progress = "Vell, little man? Vere you successful?", completion = "Very goot!\n\nYou have earned yourself a place at zhe ritual.\n\nYou shall be among zhe first to velcome Gobbles back to his... original form.", sourceObjectiveStatus = "unverified-source-field" }
quests[27944] = { id = 27944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning the Brood", description = "We have been trying to get a foothold in The Darkwood for weeks now but that forest is infested with spiders.  Do me a favor and see if you can thin them out enough for us to set up an attack.\n\nCareful out there, I have heard reports of Horde troops nearby earlier in the week.", sourceObjective = "Kill 12 Darkwood Lurkers in The Darkwood. The Darkwood forest is just west of here, across the bridge on the central island.", completion = "Nice work on those spiders, {name}.  At this rate, we will be taking that forest in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[27945] = { id = 27945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint it Black", description = "The ground bleeds, {class}. They tear it open, as one would gouge flesh.\n\nThese cultists relish their secrecy but the very elementals they use for their misdeeds can betray them. Seek out Obsidian Stoneslaves northeast of here, among the ruined earth we have named the Black Breach.\n\nShatter their bodies and find for me a perfect heart of black diamond. I will look into this heart. And I will bare its soul.", sourceObjective = "Acquire a Black Diamond Heart.", progress = "The heart. A stone heart, of purest black. Have you found one?", completion = "<Mallia removes her eyepatch and holds the black diamond before her empty eye socket.>\n\nWhat have we, what have we - breaches, the breaches number three. Two heads, one wholly given to its master. I see the future. A hammer united. A mountain shattered. Oh - OH!\n\n<Mallia drops the diamond to the floor, covering her face with her hands.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27947] = { id = 27947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Vision of Twilight", description = "Cho'gall keeps track of his minions through powerful magical orbs: \"The Eyes of Twilight.\"\n\nIn Mount Hyjal, the Guardians of Hyjal managed to find and manipulate one to their own ends. We must do the same. I want one of those orbs, and I want to use it to peer into the very heart of Cho'gall's lair.\n\nSearch the Black Breach, across the river to the northeast, and find an Eye of Twilight. Do whatever you need to bring it back to me!", sourceObjective = "Locate an Eye of Twilight within the Black Breach.", completion = "<The Eye sits before you, humming ominously with dark energies.>\n\n<Without warning, the orb rotates, as if to look at you. You sense a malevolent presence, as though the orb is alive.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27948] = { id = 27948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sticky Task", description = "Finding supplies on the island has been difficult, to say the least.\n\nFortunately, we have found a good supply of silk in The Darkwood, just west of here.  The bad part of this story is that the silk comes from the glands on Broodmother spiders.  I need you to gather 4 of these for me.\n\nThat should be just enough to finish up this last set of shirts.", sourceObjective = "Collect 4 Sticky Silk Glands from Darkwood Broodmother spiders in The Darkwood. The Darkwood forest is just west of here, across the bridge on the central island.", progress = "Were you able to gather the sticky silk glands?", completion = "These glands will do nicely.  We are grateful for your help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27949] = { id = 27949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forgotten", description = "Many soldiers died on this island {name}.  It is only fair that we pay our respects to them in any way that we can.\n\nI need you to travel to Forgotten Hill, due west of here and release our brothers in arms' tortured souls away from this place.  Do be careful over there, reports of undead have been ongoing in the area.", sourceObjective = "Release the spirits of 6 tortured souls at Forgotten Hill. Souls can be channeled by touching your hands directly to the gravestones. Forgotten Hill is due west of here, past The Darkwood and The Restless Front.", completion = "May their souls rest in peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[27950] = { id = 27950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gobbles!", description = "At last! Zhe time has come to set my Gobbles free of zhat nasty curse!\n\nPay attention now, {race}, and stay on guard. Zhere can be no interruptions vhile I perform zhe ritual.\n\nLet me know vhen you haf secured zhe perimeter!\n\nNow, move it!", sourceObjective = "Schnottz wants you to speak with him when you are prepared to witness the ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[27951] = { id = 27951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We All Must Sacrifice", description = "<The eye speaks to you, its 'voice' reverberating as if coming from everywhere at once.>\n\nYou seek my sight, {race}? My powers come at a price. These disciples of the Twilight have been honoring me with the blood of Wildhammer dwarves from the nearby ruins, but still I thirst. Perhaps you can do better.\n\nSlay my old masters, and my vision is yours. Honor me with the slaughter of the Shaman of the Black. Blood is blood, after all.", sourceObjective = "Slay 10 Shaman of the Black.", progress = "I have been watching you, {race}.", completion = "<The Eye glimmers darkly, colors swirling about its dusky surface.>\n\nAh, the succulent thrill of life extinguished. Do you feel it, {class}? Do you relish it as I do?\n\nNo, I see not. You fight to protect the lives of others. Pity.", sourceObjectiveStatus = "unverified-source-field" }
quests[27952] = { id = 27952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Explorers", description = "We have a contingent of the Explorers' League in the chamber just to the northwest inside the temple.\n\nThey've been making increasing noises about something that the Twilight's Hammer is up to.\n\n{name}, would you be a dear and see what they need?", sourceObjective = "Speak with Explorer Mowi at the Temple of Earth in Deepholm.", completion = "Oh gosh! Someone's finally here to help us?", sourceObjectiveStatus = "unverified-source-field" }
quests[27953] = { id = 27953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reliquary", description = "We have a contingent of the Reliquary in the chamber just to the northeast inside the temple.\n\nThey've been making increasing noises about something that the Twilight's Hammer is up to.\n\n{name}, would you be a dear and see what they need?", sourceObjective = "Speak with Examiner Rowe at the Temple of Earth in Deepholm.", completion = "Ah, it's about time someone came to speak with us on matters most urgent.", sourceObjectiveStatus = "unverified-source-field" }
quests[27954] = { id = 27954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eyes Have It", description = "Very well then, {race}. You have purchased my services in blood. Take me back to Garona Halforcen.\n\nOh yes, I already know where you're taking me. Garona's relentless quest for vengeance is no secret. It will be a delight to watch it unfold.", sourceObjective = "Take the Eye of Twilight to Garona Halforcen at Bloodgulch in Twilight Highlands.", progress = "Did you have any luck within the Black Breach?", completion = "You found one? I've been searching everywhere. Give it here!\n\nSome of these eyes are won over with riddles or verse. Others require magic. What did this one demand? Ah, it's no matter. What matters is that it's ours.", sourceObjectiveStatus = "unverified-source-field" }
quests[27955] = { id = 27955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye Spy", description = "This terrible thing makes my hair stand on end. Cho'gall uses these to control his minions - now it's time to use it against him.\n\nLet me see... hmm, it's all cloudy. All I can see is you. Why is it showing me you?\n\n<Garona sets the eye out in front of her.>\n\nLook into the eye and tell me what you see. Peer into Cho'gall's lair! What is he doing? Is he heavily guarded? Tell me!", sourceObjective = "Peer into the Eye of Twilight for Garona.", progress = "What did the Eye show you?", completion = "You've gone pale, {class}. What did the Eye show you?\n\nYou saw Cho'gall? Wait - Cho'gall saw you? He's watching us? He's watching us right now!?\n\nDamn this stupid dark magic! I'm going to have to infiltrate Cho'gall's stronghold myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[27956] = { id = 27956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk's Task", description = "Lunk came from the Badlands.  Other ogres try to make Lunk fight.\n\nLunk hate fighting.  Lunk want to learn.\n\nLunk sees machines to the south.  Machines made of gears.\n\nMaybe if you ask nicely, machines will give you some gears?  Then maybe Lunk can have a gear, and learn about machines too.", sourceObjective = "Obtain 15 Tempered Flywheels from Tempered War Golems.", progress = "You get gears?  How you get them?", completion = "You didn't... KILL the machines to get these, right?.\n\n<Lunk looks upset.>\n\nRight?", sourceObjectiveStatus = "unverified-source-field" }
quests[27957] = { id = 27957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk No Kill", sourceObjective = "No!  You are the same as Thorium Brotherhood dwarf.\n\n\"Kill dwarf.  Kill spider.  Kill machine.  Kill, kill, kill.\"\n\nLunk come to gorge to go on adventure, not to go on murder spree.\n\nGoodbye, {race}.  You kill too much.", sourceObjectiveStatus = "unverified-source-field" }
quests[27958] = { id = 27958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Antivenom", description = "Shame that Lunk left.  I was beginning to enjoy his company.\n\nOh well, back to work!\n\nI'm the closest thing that this expedition has to a medical officer, and I'm running low on antivenom.  We tend to need a lot of antivenom.\n\nThe key to a proper antivenom is ALWAYS to start with the poison itself.  The glassweb spiders nearby should be a good place to start.  If you kill them, you can probably extract some venom from the sacs within their jaws.", sourceObjective = "Obtain 14 samples of Glassweb Venom.", progress = "Well well, you certainly operate quickly!  You do have the venom, right?", completion = "This... this is way more than I expected.  This will last us for months!", sourceObjectiveStatus = "unverified-source-field" }
quests[27959] = { id = 27959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk's Adventure: Spider Rider", description = "Lunk sees you like to kill things.  Let Lunk teach you another way.\n\nLunk always wanted to ride on spider's back.  Looks like fun.  Spiders move too fast, though.  Always slip away.\n\nWe work together.  You fight spider until it gets weak and tired.  Then Lunk jump on spider's back and ride around.\n\nMaybe Lunk even gather some venom for you!  No have to kill!", sourceObjective = "Weaken 7 Glassweb Spiders so Lunk can ride them.", sourceObjectiveStatus = "unverified-source-field" }
quests[27960] = { id = 27960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fewer, the Better", description = "I'm not much of a fighter... I'm more of a mining dwarf.  Same goes for Jack and Pris.  And Lunk... well, you'd think he'd be a big fighter, but he's the biggest wimp of all of us.\n\nWhat I'm saying is, it's good that you came here when you did.\n\nIt seems likely that we in the Thorium Brotherhood are going to be fighting the other Dark Iron dwarves soon.  I'm thinking we should pick off some of their finest before the war starts in earnest.  Start with the geologists and watchmen to the south.", sourceObjective = "Slay 10 Dark Iron Geologists or Dark Iron Watchmen.", completion = "Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27961] = { id = 27961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Place", description = "The gorge is an unforgiving place.  We don't get a whole lot of fuzzy wildlife wandering around here.\n\nWe tried bringing in some wild game, but they haven't fared well at all.  There's just no food for them to eat.  Now the nearby spiders - which were already dangerous - are getting big and fat on chicken meat.\n\nWe'll never get rid of all the spiders, but we can salvage what few chickens remain.  Not only will you be feeding the Brotherhood, you'll be saving them a painful death by spider bite.", sourceObjective = "Obtain 8 Ash Chickens.", progress = "Those poor animals.", completion = "You've got quick hands if you were able to gather this many in such a short time.\n\nExcellent work, {name}.  I'll make sure these ones don't go to waste.", sourceObjectiveStatus = "unverified-source-field" }
quests[27962] = { id = 27962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lumbering Relic", description = "Margol the Rager's an old thunder lizard seen round these parts.  Legend has it that he's been here in the gorge since before it was even a gorge.  Legend also has it that he ate my brother Barnabas.\n\nI don't care how old he is or what kind of magic he shoots out of his nose.  I just want him dead.  For Barnabas' sake.\n\nYou'll find him wandering the cliffs to the south of here.", sourceObjective = "Obtain Margol's Gigantic Horn.", progress = "Bring me the horn, {name}.", completion = "Yup, this was Margol's horn alright.  No doubt about it.\n\nBarnabas was a digger, like me.  He never stood a chance in combat against the beast.  I'm glad you were here to set things right.", sourceObjectiveStatus = "unverified-source-field" }
quests[27963] = { id = 27963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Master... But Who?", description = "You've arrived just in time.\n\nHere's the skinny: the Dark Iron dwarves in the gorge have been acting strangely, and the Thorium Brotherhood intends to find out why.  Overseer Oilfist doesn't like surprises.\n\nWe suspect that they're following orders from some new leader.  I have reason to believe that Gravius Grimesilt, just south of here, knows who it is.\n\nEven here in Searing Gorge, we've begun to hear tales of your exploits, {name}.  You should have no problem with Grimesilt.", sourceObjective = "Obtain the Dark Iron Memo from Gravius Grimesilt at Grimesilt Worksite.", progress = "Any news?", completion = "Let's see... Overseer Maltorius... we're quite familiar with him and his work.\n\nWhat's this?  The \"archduke\"?  That sounds promising.", sourceObjectiveStatus = "unverified-source-field" }
quests[27964] = { id = 27964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dig-Boss Dinwhisker", description = "Grimesilt wasn't as high up on the chain as I thought.  We'll have to take out his superior and find out what he knows.\n\nDig-Boss Dinwhisker's his name, and he runs the Dark Iron digging operations within the Cauldron, just northwest of here.  His excavators and footmen patrol the eastern side of the Cauldron, digging downward, day and night.\n\nHe's not known to show his face out in the field very often, but if you slay enough of his men, he'll be forced to come out and deal with you.", sourceObjective = "Kill Dark Iron Excavators and Dark Iron Footmen within the Cauldron until Dig-Boss Dinwhisker appears. Then slay Dig-Boss Dinwhisker and obtain his Dark Ember.", progress = "If Dinwhisker doesn't have what we seek, I'm not sure what we'll do next.", completion = "A... an ember?  What is this thing?", sourceObjectiveStatus = "unverified-source-field" }
quests[27965] = { id = 27965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thorium Point: The Seat of the Brotherhood", description = "Did... did you see that?  This is the missing piece we've been looking for!  We have to take this information back to someone at Thorium Point.\n\nThe Dark Irons have been known to consort with the firelord in the past, but never before have they brought their kind this far out into Searing Gorge.\n\nThorium Point is west and north of here.  You will find it nestled in the cliffs that overlook Pyrox Flats.  Take this information straight to Overseer Oilfist.", sourceObjective = "Report to Overseer Oilfist at Thorium Point in Searing Gorge.", completion = "Do I know you, {race}?\n\n\n\nSounds like another one of Ragnaros' minions.  I don't like the sound of that.", sourceObjectiveStatus = "unverified-source-field" }
quests[27966] = { id = 27966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging the Remains", description = "Forgotten Hill has been overrun with zombies and ghouls ever since we reclaimed this wretched isle.  We have tried to clear them out many times but they always seem to come back.\n\nOne of our lieutenants recommended taking the ghouls' bones when we kill them in hopes that they can't reincarnate overnight.  Think you can help us out with this one?", sourceObjective = "You need to recover 9 Cursed Femur bones from the ghouls that inhabit Forgotten Hill. Forgotten Hill is on the west side of the island, just past The Forgotten Front.", progress = "Were you able to recover the femur bones?  Better for you to try than me.", completion = "I didn't think you would be able to do it, {name}.  You are just full of surprises aren't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[27967] = { id = 27967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Lieutenant Connor", description = "The first time I heard about Lt. Connor, I was just a young recruit in the Stormwind stockades.  None of us could believe he ended up here on Tol Barad.  Sadly, he still roams these wretched islands, wreaking havoc on our troops morale.\n\nI need you to put an end to his misery... and ours.", sourceObjective = "Find and kill First Lieutenant Connor at Forgotten Hill. You will find Forgotten Hill on the far west side of the island.", completion = "Hey, you made it back alive!  Can't say you were the first one to try this task, but you are definitely the first one to make it back alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[27968] = { id = 27968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury of the Pack", description = "Ah, the sweet scent of victory! My men should be tearing Godfrey to pieces even as we speak. Go up to his domain and collect your share of the spoils - you've earned it!\n\nYou'd think that he would have been more difficult to defeat...", sourceObjective = "Kill Lord Godfrey.", progress = "Let's get going.", completion = "We did it, {name}! At terrible cost... but victory is ours.\n\nThis keep could serve well as a home for me and my pack, though we tend to prefer more natural habitats.\n\nIt may be best to leave it as a reminder of Godfrey's betrayal and of the Bloodfang warriors that died here in battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[27969] = { id = 27969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Yourself Useful", description = "Gobbles vill be sorely missed, but zhe mission must not suffer.\n\nPerhaps zhere is somezhink you can do to redeem yourself.\n\nTake vone of zhe uniforms you recovered. Vhile vearink it, my vorkers vill not behave so... aggressively.\n\nLately, zheir morale has been a bit lackink. Some of zhe vorkers are refusing to perform zheir labors.\n\nAuch, zhe audacity!\n\nFind zhese lazy imbeciles and convince zhem zhat zhey must get to vork... or else!", sourceObjective = "Commander Schnottz wants you to persuade 6 Slacking Laborers to get to work.", progress = "Vhell, {race}? Vere you... persvasive?", completion = "Vell done, {class}.\n\nZhere may be hope for you yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27970] = { id = 27970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain P. Harris", description = "The Cape of Lost Hope has been a sore in our side for weeks here on Tol Barad.  Half of our supply ships end up on the rocks down there.\n\nTo make matters worse, it's been overrun by a gang of undead sailors.  We have tried thinning the ranks, but they just seem to keep coming back.  Our last resort is to try and take out the captain that they report to.  You should be able to find him on a ship, just off the shoreline.\n\nOh, and I hope you are not too scared of sharks.", sourceObjective = "You have been tasked with killing Captain P. Harris at the Cape of Lost Hope. The Cape of Lost Hope can be found northwest of here, along the coast. Just look for the shipwrecks.", completion = "You did it!  Maybe we can finally get some ships into port now.  Thank you {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27971] = { id = 27971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rattling Their Cages", description = "We have been having issues with the undead down at the Cape of Lost Hope for a while now.  Every time a new ship wrecks, they end up getting more undead to join their ranks.\n\nCan you do us a favor and thin out the ranks up there?  I know you won't be able to kill them all, but anything you can do will help at this point.\n\nKeep an eye out for horde, we have been getting reports of them ambushing the beach lately.", sourceObjective = "Camp Coordinator Brack has asked you to kill 8 Shipwrecked Sailors at the Cape of Lost Hope. The cape is located due northwest of here, on the beach.", completion = "Nice work on the undead up there {name}.  We really appreciate the help.", sourceObjectiveStatus = "unverified-source-field" }
quests[27972] = { id = 27972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boosting Morale", description = "Morale is low these days, {name}.  We make every effort we can to keep the troops in high spirits but we are running low on our main supply of morale booster... rum.\n\nI have been getting reports from our infantry to the south that the shipwrecks on the Cape of Lost Hope still have a good supply of southsea rum in their wrecked hulls.  Can you head up there and investigate?\n\nBring back any rum you can find.", sourceObjective = "You have been asked to recover 6 Barrels of Southsea Rum from the shipwrecks on the Cape of Lost Hope. The cape can be found north of here, along the coast.", progress = "Were you able to recover the rum?  I would try but I am deathly afraid of the water.  Not to mention that crazy shark.", completion = "This rum will really help us out, {name}.  They might not feel great in the morning but at least they will go to sleep happy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27973] = { id = 27973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watch Out For Splinters!", description = "Have you been over to the Wellson Shipyard yet, {name}?  Best to stay away from there unless you have a good reason to venture in.  Unfortunately, that is exactly what I need you to do.\n\nYou see, we have been short on supplies ever since we recaptured the island.  That ghost ridden shipyard is overflowing with lumber but every time we send an escort to recover the lumber, they never make it back.\n\nCan you help us out?", sourceObjective = "Sergeant Gray has asked you to recover 15 pieces of Shipyard Lumber from the Wellson Shipyard. The lumber can be recovered from the ghosts in the shipyard or found lying around the premises. The shipyard can be found northwest of here, on the coast.", progress = "Did the ghosts scare you off?", completion = "I didn't think you would be able to do it, {name}.  You are just full of surprises aren't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[27974] = { id = 27974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Land is Our Land", description = "Did you think that a handful of worgen vermin could stop me? Hah!\n\nShadowfang Keep was part of the Lordaeron kingdom in life, so it is quite fitting that it should belong to the Forsaken in death. Godfrey and his accomplices are minor obstacles at best, and of course we're all happy to take them out for their treachery against the Dark Lady.\n\nAshbury has positioned himself near the front of the keep, leaving him wide open to attack. Start us out on the right foot, would you?", sourceObjective = "Kill Baron Ashbury.", progress = "Don't test my patience and good will.", completion = "Ah, very well done! They've gotten a hold of powerful allies, but clearly nothing a {class}-champion of the Banshee Queen can't handle!", sourceObjectiveStatus = "unverified-source-field" }
quests[27975] = { id = 27975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Foreman Wellson", description = "Foreman Wellson has been a pain in our side since we got here.  His shipyard holds a large amount of supplies that would be extremely useful to us... if we could get to them.\n\nHe keeps a close watch over his minions and makes it very difficult for us to get a foothold on the shipyard.  I need you to take out Wellson for good this time.  Be careful {name}, we have been receiving reports of filthy Horde all around the area.", sourceObjective = "Kill Foreman Wellson at the Wellson Shipyard. The shipyard can be found northwest of here, on the western coast.", progress = "Were you able to \"take care of\" Foreman Wellson?", completion = "Great work {name}.  I will report your efforts to our highest in command immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[27976] = { id = 27976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curse These Fat Fingers", description = "Unfortunately, I can't dish out the beats like I used to, due to this here fat finger problem.  Ye see, the climate out here combined with the lack o' air pressure makes me fingers expand.  They're like gigantic Thelsamar Blood Sausages, they are...\n\nYe're gonna have to carry out me orders of business and what have ye.\n\nFirst on me agenda: Poundin' the livin' daylights out o' the heavy war golems o' the Gorge.  Get crackin'.", sourceObjective = "Kill 12 Heavy War Golems.", completion = "Ye're a good lad, ye are. I got ye a lil' present fer yer troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[27977] = { id = 27977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recon Essentials", description = "We used to have more stuff around here.  I think there was a spyglass somewhere nearby, along with a smithing tuyere.\n\nI'm pretty certain that they've been stolen by Dark Iron dwarves.  Yes, I know that I'm a Dark Iron dwarf!  I'm talking about the bad ones that live down in that gorge.\n\nYou'd best check the steamsmiths that work just south of here.  They'd be most likely to use tools like these.", sourceObjective = "Find and return the Smithing Tuyere and Lookout's Spyglass.", progress = "If you're here for the reward, you're gonna have to give me the stolen goods.", completion = "Fantastic work!", sourceObjectiveStatus = "unverified-source-field" }
quests[27978] = { id = 27978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghostbuster", description = "See that hill just beyond our base camp?  That's Largo's Overlook and it's not a fun place to setup camp next to.  We have been dealing with those spirits and spectres ever since we setup base camp.\n\nCan you head up there and let them know we don't plan on leaving anytime soon?  A few good kills on their ranks should put them in line.\n\nThanks for your help on this, {name}.", sourceObjective = "Kill 14 ghosts of any type at Largo's Overlook, just northeast of base camp.", completion = "Great work, {name}!  We should not hear from the ghosts again anytime soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[27979] = { id = 27979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Ministry", description = "I got one more assignment for ye.  This one comes straight down from the Overseer himself.  Seems he was pretty shook up once he heard about that \"Archduke\" ye discovered.\n\nHe's asked for us to hunt down three Twilight ministers that work over in Firewatch Ridge, to the west.  Kiyuubi, Letherio, and Finister are their names, and they each carry some sort o' special rock.  Combine all three and bring 'em back here.\n\nListen, when the Overseer gives orders, ye don't ask questions.  Ye just do it.", sourceObjective = "Obtain Kiyuubi's Spherule, Letherio's Spherule, and Finister's Spherule, then combine them into a Twilight Tripetricine.", progress = "Ye got the thing?", completion = "<Hansel weighs the stone in his hands.>\n\nThis thing is strange, {name}.  I don't know what to make of it.  It ain't natural, that's for sure.", sourceObjectiveStatus = "unverified-source-field" }
quests[27980] = { id = 27980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spiders Have to Go", description = "Normal-size spiders, I can handle.\n\nGiant glassweb spiders make me uncomfortable, but they're far enough away that I don't worry too much.\n\nBut lava spiders?  <Lolo shudders.>  Lava spiders are SCARY.  They're enormous spiders.  That live in LAVA.\n\nI just got paid for my last week of work, and I'll pay you well to kill those things.  You'll find 'em all over Searing Gorge.", sourceObjective = "Slay 9 Lava Spiders within Searing Gorge.", completion = "There's no way you coulda killed all the spiders in the gorge, but you definitely made a dent.\n\nFine, here's what I promised ya.  Don't spend it all in one place.  Unless it's at Thorium Point.", sourceObjectiveStatus = "unverified-source-field" }
quests[27981] = { id = 27981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heat That Just Don't Quit", description = "We smith, we smelt, we roast up whatever spider meat we can get.  Bush chicken if we're lucky.  Point is, all o' this work means we need lots and lots of fire.\n\nGood thing we're smack dab in the middle of firetown.\n\nO' course, the best fire comes from the elementals.  You'll find 'em all over Searing Gorge, but always near lava.  Here, take these flasks and use 'em on the elementals.\n\nOh, did I mention the elementals gotta be alive when you gather your sample?", sourceObjective = "Obtain 10 Filled Furnace Flasks. You must use the Furnace Flasks on living elementals within Searing Gorge.", progress = "Oilfist says he's gonna have us makin' firebombs soon.  All the more need for those flasks.", completion = "Yeeeeeeowch!  Don't just go puttin' this stuff into a dwarf's open hand.  This stuff is burnin' up!\n\nNow me hands are gonna get even more swollen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27982] = { id = 27982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Collars", description = "Have ye seen the ridiculous necklaces those Twilight's Hammer cultists all wear?  The gems on those things are bigger than Hansel's fist!\n\nA few hamburger-sized jewels like that, and Burninate over there could really push his blacksmithing business to the next level.  Fetch those collars, and he'll make it worth your while.", sourceObjective = "Obtain 20 Twilight Collars.", progress = "A ruby-hilted hammer... it has a nice ring to it.", completion = "Hmm... the gems looked... sparklier from afar.  Up close, they look kind of dingy.\n\nAh well!  A little spit and polish should do the trick, and if not, I can use 'em to practice my disenchanting.", sourceObjectiveStatus = "unverified-source-field" }
quests[27983] = { id = 27983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk's Adventure: Cranky Little Dwarfs", description = "What you doing?  Why you kill?\n\nYou need to get things from dwarfs?  Ah, Lunk understand.  Lunk have a better way.\n\nListen: you go fight dwarf, but do not kill!  Just fight until dwarf get tired.  Then Lunk will help dwarf fall asleep.  Dwarfs probably just cranky because they don't get sleep.\n\nCome on!  Trust Lunk.", sourceObjective = "Weaken 7 Dark Iron Steamsmiths so Lunk can help them fall asleep.", sourceObjectiveStatus = "unverified-source-field" }
quests[27984] = { id = 27984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunthistle's Tale", description = "Will you assist me, mortal? Hear my tale.", sourceObjective = "Hear Zamael tell his tale.", progress = "Allow me to finish my story.", completion = "I have accepted my fate here in this cage, but the prayer must be found.", sourceObjectiveStatus = "unverified-source-field" }
quests[27985] = { id = 27985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prayer to Elune", description = "Will you assist me, mortal?  Will you find the prayer to Elune?\n\nAs I stated, the prayer was etched onto a golden tablet.  I believe they hold it within one of their vile chests, near the entrance to their cave at the bottom of the ridge.\n\nIf you do recover my prayer, don't bring it back to me.  Instead, take the time to read through it.\n\nAbsolution may be asking too much, based on the sins I've committed.  But that won't stop me from holding out hope.You will learn:", sourceObjective = "Find and read the Prayer to Elune.", sourceObjectiveStatus = "unverified-source-field" }
quests[27986] = { id = 27986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Hall of the Mountain-Lord", description = "The Thorium Brotherhood doesn't maintain a militia - just a few guards, and me, and that's it.  If we're to successfully strike against the Dark Irons of the gorge, we're gonna need help.\n\nMountain-Lord Rendan sits atop that tower across the gorge, to our south.  He doesn't consort with Twilight folks or fire elementals, but he hasn't joined the brotherhood either.  Maybe it's time we paid him a visit.  With his help, we might just stand a chance.", sourceObjective = "Speak with Mountain-Lord Rendan at Iron Summit in Searing Gorge.", completion = "And who might you be?\n\nAh, an emissary from the Thorium Brotherhood.  They're looking for my support?  Fine, I might be willin' to help out...\n\n...for a price.", sourceObjectiveStatus = "unverified-source-field" }
quests[27987] = { id = 27987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannonball!", description = "Largo and his minions have been stealing our supplies ever since we setup camp here.  It's frustrating to say the least.\n\nWe have heard reports that he is stockpiling cannonballs in the towers overlooking the water up on his overlook.  Can you head up there and try to recover some of them for us?\n\n{name}, don't forget to keep a watch out for horde too.", sourceObjective = "You need to recover 4 Stacks of Cannonballs from Largo's Overlook for Sergeant Gray. You can find Largo's Overlook just northeast of the base camp.", progress = "Did you find the cannonballs?", completion = "Good job on the recovery effort, {name}. These cannonballs should last us a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[27988] = { id = 27988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plague...Plague Everywhere!", description = "The best part about this plague is that even when it visually fades away, the remaining residue is still quite potent! However, we still have an enormous area to cover before we're done, with plenty of Godfrey's defenses in the way.\n\nIt appears that the spirits that served Baron Silverlaine and Commander Springvale in life now guard them in death, and Godfrey is using them to deter us. Show them all the iron will of the Forsaken!", sourceObjective = "Kill Baron Silverlaine and Commander Springvale.", progress = "A couple bodiless spirits aren't going to best you, are they?", completion = "Cromush has both a thick skull and a fool's brain, and we'll use that to our advantage. By the time anybody finds out about the plague's true potency, it'll be far too late.\n\nThank you for keeping quiet during his tirade. I promise you won't regret it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27989] = { id = 27989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruumbo Demands Honey", description = "Ruumbo hungers!\n\nThe Deadwood jerks have stolen all their honey from the Timbermaw tribe! We saw...er, Ruumbo saw them do it! Now Ruumbo must have that honey!\n\nTake this... this stick! Yes, this stick. Take this stick and use it to steal the honey from their beehives in Deadwood Village.\n\nRuumbo must have as much honey as possible. This is vital.", sourceObjective = "Collect 10 Deadwood Honey Globs from the hives in Deadwood Village using Ruumbo's Honey Stick.", progress = "Ruumbo can smell whether you have honey or not!", completion = "Honey! Delicious honey!\n\nWell done, ugly creature! You may put the honey...put the honey down right there. No, to the left. Yes, there. Just leave it there.", sourceObjectiveStatus = "unverified-source-field" }
quests[27990] = { id = 27990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlezone", description = "It vould appear zhat anozher opportunity has arisen for you to redeem yourself, {race}.\n\nZhis little emergency has set me back a few tank gunnahs.\n\nYou zhink you have vhat it takes to fill in for vone of zhem?\n\nMy tanks are just vest of zhe camp. Get out zhere and put an end to zhis silliness!", sourceObjective = "Commander Schnottz wants you to man one of the siege tank turrets and use it to defeat 7 Decrepit Watchers, then report back to him.", progress = "Vell?\n\nHas our little situation been brought under control?", completion = "Auch!\n\nIf I vere an inch or two taller, I'd be dead!", sourceObjectiveStatus = "unverified-source-field" }
quests[27991] = { id = 27991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Overlook Back", description = "There is only one way for us to take Largo's Overlook back.\n\nI think you know what we need to do {name}.  Largo is pretty paranoid these days so you should be able to find him on top of the tower, looking for his imaginary navy to finally arrive.", sourceObjective = "Sergeant Gray has asked you to kill Commander Largo at Largo's Overlook. The overlook is just northeast of the base camp.", progress = "Were you able to take out Largo?", completion = "Ha, we finally got Largo!  Nice one, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27992] = { id = 27992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magnets, How Do They Work?", description = "Getting useful machine parts out here on the island has been difficult, {name}.  We have been trying to repair the broken siege engines here in camp but we keep running out of useful parts.\n\nOur second regiment reported some wrecked out siege engines in a old battlefield to the west.  Maybe we could find some parts over there?\n\nYou are going to have trouble finding anything in that old battlefield so take this magnetized scrap collector and put it to some good use.", sourceObjective = "You have been tasked with recovering 7 pieces of Siege Engine Scrap. Use the Magnetized Scrap Collector in The Restless Front to find the scraps. The Restless Front is due west, just past the second bridge.", progress = "Did that magnet contraption actually work?", completion = "These parts will really help us out, {name}!  Who would have thought you can find stuff this useful in all that old junk?", sourceObjectiveStatus = "unverified-source-field" }
quests[27993] = { id = 27993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take it to 'Em!", description = "We was lucky to escape, {class}. I'm not sure I'd feel right if we didn't take care of them ambushers.\n\nHows about you git back up to Khartut's tomb and give them little buggers what fer!\n\nIt's off to the northeast, just inside the entrance to Uldum if'n I recollect correctly.\n\nWhat're you looking at? I sure ain't in no condition to do it!", sourceObjective = "Mack wants you to investigate Khartut's Tomb.", completion = "Good to see ya, kid.\n\nWould've been even better if you'd have been here to help me take care of these little savages...", sourceObjectiveStatus = "unverified-source-field" }
quests[27994] = { id = 27994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruumbo Demands Justice", description = "You! Wanderer! Bow before the might of Ruumbo, great god of the Timbermaw tribe!\n\nHear my will! The evil Deadwood tribe lives in the village behind me! They are big jerks!\n\nI mean, they... they sully my name with their wicked misdeeds! They persecute my cherished Timbermaw tribe and hurt them!\n\nI demand you inflict my justice! Defeat the Deadwood and I will give you my... my favor! Yes! The favor of RUUMBO!", sourceObjective = "Slay 15 Deadwood Furbolg of any type.", progress = "Ruumbo demands you defeat the jerks! I mean, the Deadwood tribe!", completion = "It worked!\n\nI mean, uh, YES, the will of Ruumbo has been carried out! You have done well, creature! You may have these shiny coins!", sourceObjectiveStatus = "unverified-source-field" }
quests[27995] = { id = 27995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dance for Ruumbo!", description = "You have done well, {race}! Ruumbo is pleased by your bravery, and the delicious honey you have given Ruumbo.\n\nNow, you must... you must dance! Yes!\n\nDance for Ruumbo! Dance!", sourceObjective = "Do a silly dance for Ruumbo.", completion = "Those two brats... I should have known! They were smart enough to hush whenever I went to examine the totem.\n\nI'll be sure to find them and drag them back to Timbermaw Hold by the ears! Thank you for looking into it...", sourceObjectiveStatus = "unverified-source-field" }
quests[27996] = { id = 27996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders Are For the Living", description = "Unsurprisingly, we aren't going to listen to Cromush about the plague. However, his brute strength will come in handy for muscling my men through the many foes ahead on the path to Godfrey, the most powerful being his right hand man, Lord Walden.\n\nI'll meet you in Walden's chamber after you finish him off. Then, at long last, we can completely take Shadowfang Keep for the Forsaken!", sourceObjective = "Kill Lord Walden.", progress = "You have your orders, {name}.", completion = "The time has come! Godfrey will fall!", sourceObjectiveStatus = "unverified-source-field" }
quests[27997] = { id = 27997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corruption of the Jadefire", description = "The cleansing of this forest has been a grueling process. For every success we have achieved, a new challenge has arisen.\n\nThe Jadefire satyr have been a constant nuisance. They seek to corrupt the forest just as we seek to cleanse it. Now, we have taken steps to begin eradicating them from Felwood entirely.\n\nTravel to Jadefire Glen to the west and rid the forest of their presence. You'll find the entrance just north of the walls of Deadwood Village; look for their vile banners.", sourceObjective = "Slay 12 Jadefire Satyr or Jadefire Felsworn in Jadefire Glen.", completion = "The Emerald Circle thanks you, {name}. If we all work together here, we can purge these demons from our midst.", sourceObjectiveStatus = "unverified-source-field" }
quests[27998] = { id = 27998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet, Merciless Revenge", description = "If all goes well you'll just be able to walk right into Godfrey's personal domain and take a reward fitting for such an eager young {class}.\n\nGodfrey is a cunning foe, though, so it may be wise to head up there quickly just in case you're needed. He will pay for what he did to the Dark Lady!", sourceObjective = "Kill Lord Godfrey.", progress = "Let's get going.", completion = "For a moment there, I thought all was lost. Even when surrounded by the worgen in Gilneas I had higher hopes!\n\nBut you proved me wrong {name}. I will see to it that Sylvanas herself hears of your triumph here today. Don't worry about the mess here, I will gladly see to it myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[27999] = { id = 27999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of the Doyles", description = "It seems the Doyles already joined their last fight. Iain will want to know of their fate.", sourceObjective = "Return the news of Clan Doyle to Iain Firebeard at the Firebeard Cemetery.", completion = "That's a right shame. Stubborn as they were to speak to, they were just as stubborn in a fight. Would have been good to have 'em.\n\nOnce this is done, we'll have to send some boys out to bring them back for a proper send off.", sourceObjectiveStatus = "unverified-source-field" }
quests[28000] = { id = 28000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do the Imp-Possible", description = "The satyr hide their corrupted moonwell behind an impenetrable barrier of demonic fire. Their forces must have some way of getting through it.\n\nInterrogating the satyr will be useless, but the imps they consort with will be easily swayed. I have a specific one in mind, as well...\n\nIn the foothills to the east, a lone imp has been seen wandering, far from the other demons. He should prove easy pickings. Weaken him with combat, and then use this enchanted sack to capture him. Then I'll do the talking...", sourceObjective = "Weaken Impsy and use the Enchanted Imp Sack to capture him.", progress = "Do you have an imp for me?", completion = "Imps are creatures of deception. With so many of them spotted at Shadowlurk Ridge, I'm positive something is being hidden there.\n\nOur little friend will tell us exactly how to find it... if he doesn't want to go back in the sack.", sourceObjectiveStatus = "unverified-source-field" }
quests[28001] = { id = 28001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Coward's Due", description = "We may be safe here, but there are a lot of Wildhammer who could still use support. Our wing can offer that, but we need to keep bolsterin' our forces if we're going to clear the Twilight completely.\n\nI'm going to have words with Colin Thundermar. Only a coward turns down the callin' of his people, especially in a time this dire.\n\nGo to Thundermar, find Colin and get a real explanation out of'm. I won't be putting up with cowardice in a Wildhammer leader.", sourceObjective = "Speak to Colin Thundermar in Thundermar.", completion = "Here here, WOT!? He calls ME a COWARD!?\n\nJust like a Firebeard, all hot air and not a lick of sense. I've been bearing the brunt of a Dragonmaw invasion from the south, much of Thundermar is in ruins, and do any of the other clans stick up to help? NO! Ol' Thundermar is on his own he is, and you'd better believe I'm usin' everything in my arsenal just to stem the tide.", sourceObjectiveStatus = "unverified-source-field" }
quests[28002] = { id = 28002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crisis Management", description = "There is a delicate situation that calls for the... objective discretion of an outsider.\n\nYou see, an unfortunate incident has upset some of our guests. Rest assured, our top men are sorting out the details.\n\nIn the meantime, it would be wonderful if you could calm our more squeamish visitors.\n\nHandle this well, and the furrier is sure to hear of it!", sourceObjective = "Belloc Brightblade wants you to reassure the guests at Schnottz's Landing.", completion = "Hmm, still a bit frazzled, are they?\n\nWell, you know what they say. Time heals all wounds.\n\nExcept for those of the ambassador, of course...", sourceObjectiveStatus = "unverified-source-field" }
quests[28003] = { id = 28003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Ragefire Chasm", description = "The Warchief has requested that any able-bodied adventurer head to Ragefire Chasm, just beneath the great city of Orgrimmar, immediately!\n\nThe Searing Blade is poised to launch an attack at any moment and the city guards cannot hold for much longer! If you so choose, head to Ragefire Chasm and speak with Stone Guard Kurjack, head of the defense initiative, to end the threat to Orgrimmar once and for all.", sourceObjective = "Speak with Stone Guard Kurjack.", sourceObjectiveStatus = "unverified-source-field" }
quests[28004] = { id = 28004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: The Deadmines", description = "The Warchief has requested that any able-bodied adventurer head to the Deadmines, in the distant land of Westfall, immediately!\n\nAssistance is required in the initiative to take the Defias Juggernaut for the Horde to use against the Alliance! If you so choose, head to the Deadmines and speak with Kagtha, a rogue of the Shattered Hand, to aid in the ongoing war against the Alliance.", sourceObjective = "Speak with Kagtha.", sourceObjectiveStatus = "unverified-source-field" }
quests[28005] = { id = 28005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: The Deadmines", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Deadmines, in southern Westfall, immediately!\n\nAssistance is required in stopping the reborn Defias Brotherhood from terrorizing the area! If you so choose, head to the Deadmines and speak with Lieutenant Horatio Laine, lead investigator on the case, to aid in stopping the Defias once and for all.", sourceObjective = "Speak with Lieutenant Horatio Laine.", sourceObjectiveStatus = "unverified-source-field" }
quests[28006] = { id = 28006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Wailing Caverns", description = "The Warchief has requested that any able-bodied adventurer head to the Wailing Caverns, just west of the Crossroads, immediately!\n\nNaralex must be awakened to save the Barrens! If you so choose, head to the Wailing Caverns and speak with Nalpak, one of Naralex's disciples, to help in healing the injured land.", sourceObjective = "Speak with Nalpak.", sourceObjectiveStatus = "unverified-source-field" }
quests[28007] = { id = 28007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Wailing Caverns", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Wailing Caverns, just west of the Crossroads, immediately!\n\nNaralex must be awakened to save the Barrens! If you so choose, head to the Wailing Caverns and speak with Nalpak, one of Naralex's disciples, to help in healing the injured land.", sourceObjective = "Speak with Nalpak.", sourceObjectiveStatus = "unverified-source-field" }
quests[28008] = { id = 28008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Shadowfang Keep", description = "The Warchief has requested that any able-bodied adventurer head to Shadowfang Keep, in southern Silverpine Forest, immediately!\n\nThe traitor, Lord Godfrey, must pay for what he did to Sylvanas! If you so choose, head to Shadowfang Keep and speak with Deathstalker Commander Belmont, leader of the war effort there, to help enact proper revenge.", sourceObjective = "Speak with Deathstalker Commander Belmont.", sourceObjectiveStatus = "unverified-source-field" }
quests[28009] = { id = 28009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Shadowfang Keep", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Shadowfang Keep, in southern Silverpine Forest, immediately!\n\nThe traitor, Lord Godfrey, must pay for what he did to our new allies! If you so choose, head to Shadowfang Keep and speak with Packleader Ivar Bloodfang, leader of the war effort there, to help enact proper revenge.", sourceObjective = "Speak with Packleader Ivar Bloodfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[28010] = { id = 28010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackfathom Deeps", description = "The Warchief has requested that any able-bodied adventurer head to Blackfathom Deeps, north of Zoram'gar Outpost, immediately!\n\nThe Twilight's Hammer threatens the world with its actions there! If you so choose, head to Blackfathom Deeps and speak with Je'neu Sancrea, a member of the Earthen Ring, to help stop the Twilight threat.", sourceObjective = "Speak with Je'neu Sancrea.", sourceObjectiveStatus = "unverified-source-field" }
quests[28011] = { id = 28011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackfathom Deeps", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Blackfathom Deeps, west of Astranaar, immediately!\n\nThe Twilight's Hammer threatens the world with its actions there! If you so choose, head to Blackfathom Deeps and speak with Sentinel Aluwyn, head of the night elf effort there, to help stop the Twilight threat.", sourceObjective = "Speak with Sentinel Aluwyn.", sourceObjectiveStatus = "unverified-source-field" }
quests[28012] = { id = 28012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Stormwind Stockade", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Stormwind Stockade, inside his highness' own city, immediately!\n\nA mass riot has begun within! If you so choose, head to the Stockade and speak with Rifle Commander Coe, head rifleman of the Stockade guard, to help quell the uprising.", sourceObjective = "Speak with Rifle Commander Coe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28013] = { id = 28013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Gnomeregan", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Gnomeregan,west of Ironforge, immediately!\n\nThe Gnomes need help reclaiming their city! If you so choose, head to Gnomeregan and speak with Murd Doc, recruiter for the G-Team, to help in the mission.", sourceObjective = "Speak with Murd Doc.", sourceObjectiveStatus = "unverified-source-field" }
quests[28014] = { id = 28014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Razorfen Kraul", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Razorfen Kraul, in the southernmost part of the Southern Barrens, immediately!\n\nAuld Stonespire needs assistance in stopping the quilboar before they begin to spread further! If you so choose, head to Razorfen Kraul and speak with Auld Stonespire, a wise and respected shaman, to help stop the menace.", sourceObjective = "Speak with Auld Stonespire.", sourceObjectiveStatus = "unverified-source-field" }
quests[28015] = { id = 28015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Razorfen Kraul", description = "The Warchief has requested that any able-bodied adventurer head to Razorfen Kraul, in the southernmost part of the Southern Barrens, immediately!\n\nAuld Stonespire needs assistance in stopping the quilboar before they begin to spread further! If you so choose, head to Razorfen Kraul and speak with Auld Stonespire, a wise and respected shaman, to help stop the menace.", sourceObjective = "Speak with Auld Stonespire.", sourceObjectiveStatus = "unverified-source-field" }
quests[28016] = { id = 28016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Graveyard", description = "The Warchief has requested that any able-bodied adventurer head to the Scarlet Monastery Graveyard, northeast of the Undercity, immediately!\n\nDark Ranger Velonara has requested more soldiers to help her begin her assault! If you so choose, head to the Scarlet Monastery Graveyard and speak with Dark Ranger Velonara, a clever fighter indeed, to do your part.", sourceObjective = "Speak with Dark Ranger Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28017] = { id = 28017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Library", description = "The Warchief has requested that any able-bodied adventurer head to the Scarlet Monastery Library, northeast of the Undercity, immediately!\n\nDark Ranger Velonara has requested more soldiers to help her take out their defenses! If you so choose, head to the Scarlet Monastery Library and speak with Dark Ranger Velonara to do your part.", sourceObjective = "Speak with Dark Ranger Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28018] = { id = 28018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Armory", description = "The Warchief has requested that any able-bodied adventurer head to the Scarlet Monastery Armory, northeast of the Undercity, immediately!\n\nDark Ranger Velonara has requested more soldiers to help her take out their offensive capabilities! If you so choose, head to the Scarlet Monastery Armory and speak with Dark Ranger Velonara to do your part.", sourceObjective = "Speak with Dark Ranger Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28019] = { id = 28019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Cathedral", description = "The Warchief has requested that any able-bodied adventurer head to the Scarlet Monastery Cathedral, northeast of the Undercity, immediately!\n\nDark Ranger Velonara has requested more soldiers to help her put the final nail in the Scarlet Crusade's coffin! If you so choose, head to the Scarlet Monastery Cathedral and speak with Dark Ranger Velonara to relish in Forsaken victory!", sourceObjective = "Speak with Dark Ranger Velonara.", sourceObjectiveStatus = "unverified-source-field" }
quests[28020] = { id = 28020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Graveyard", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Scarlet Monastery Graveyard, northeast of the Undercity, immediately!\n\nJoseph the Awakened, a former crusader, has requested aid to help him take out the leaders there and reform the crusade! If you so choose, head to the Scarlet Monastery Graveyard and speak with Joseph the Awakened to do your part.", sourceObjective = "Speak with Joseph the Awakened.", sourceObjectiveStatus = "unverified-source-field" }
quests[28021] = { id = 28021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Library", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Scarlet Monastery Library, northeast of the Undercity, immediately!\n\nJoseph the Awakened has requested more aid to help him rid the Crusade of their magi! If you so choose, head to the Scarlet Monastery Library and speak with Joseph the Awakened to help bring the crusaders back into the Light.", sourceObjective = "Speak with Joseph the Awakened.", sourceObjectiveStatus = "unverified-source-field" }
quests[28022] = { id = 28022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Armory", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Scarlet Monastery Armory, northeast of the Undercity, immediately!\n\nJoseph the Crazed has requested help to kill Herod, the Scarlet Champion! If you so choose, head to the Scarlet Monastery Armory and speak with Joseph the Crazed to help him out.", sourceObjective = "Speak with Joseph the Crazed.", sourceObjectiveStatus = "unverified-source-field" }
quests[28023] = { id = 28023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scarlet Monastery Cathedral", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Scarlet Monastery Cathedral, northeast of the Undercity, immediately!\n\nJoseph the Insane needs help to take over the Scarlet Crusade at long last! If you so choose, head to the Scarlet Monastery Cathedral and speak with Joseph the Insane to take a part in history.", sourceObjective = "Speak with Joseph the Insane.", sourceObjectiveStatus = "unverified-source-field" }
quests[28024] = { id = 28024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Razorfen Downs", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Razorfen Downs, in Thousand Needles, immediately!\n\nThe mysterious Koristrasza needs help to stop the Scourge-Quilboar alliance! If you so choose, head to Razorfen Downs and speak with Koristrasza to lend her your skills.", sourceObjective = "Speak with Koristrasza.", sourceObjectiveStatus = "unverified-source-field" }
quests[28025] = { id = 28025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Razorfen Downs", description = "The Warchief has requested that any able-bodied adventurer head to Razorfen Downs, in Thousand Needles, immediately!\n\nThe mysterious Koristrasza needs help to stop the Scourge-Quilboar alliance! If you so choose, head to Razorfen Downs and speak with Koristrasza to lend her your skills.", sourceObjective = "Speak with Koristrasza.", sourceObjectiveStatus = "unverified-source-field" }
quests[28026] = { id = 28026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Uldaman", description = "The Warchief has requested that any able-bodied adventurer head to Uldaman, near New Kargath, immediately!\n\nThe Reliquary and its leader, High Examine Tae'thelan Bloodwatcher, requires assistance in obtaining powerful relics within! If you so choose, head to Uldaman and speak with the High Examiner to aid their cause.", sourceObjective = "Speak with High Examiner Tae'thelan Bloodwatcher.", sourceObjectiveStatus = "unverified-source-field" }
quests[28027] = { id = 28027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Uldaman", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Uldaman, in the Badlands, immediately!\n\nThe Explorers' League, under Lead Prospector Durdin, requires assistance in braving great danger in pursuit of knowledge! If you so choose, head to Uldaman and speak with Lead Prospector Durdin to help them out.", sourceObjective = "Speak with Lead Prospector Durdin.", sourceObjectiveStatus = "unverified-source-field" }
quests[28028] = { id = 28028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege!", description = "That Overseer Oilfist couldn't'a picked a worse time to ask me to join a fight.  My summit's already under siege!\n\nIt's nothin' my guards can't handle, but still, it won't be easy for me to just pick up and send some dwarves into that infernal gorge.\n\nTell ya what: you take out their marksman that're holding our fortress under siege, and I'll consider your offer.  Ye'll find 'em slinkin' around the flats to the east.", sourceObjective = "Slay 9 Dark Iron Marksmen.", completion = "If nothin' else, you bought us some time, and some room to open up our supply lines through this siege.\n\nYer a fine {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28029] = { id = 28029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set Them Ablaze!", description = "I'm not sure if ye've noticed, but my tower's much taller than any o' the other towers here around the Gorge.  Some dwarves pride themselves at how deep they can dig, but not me.  Sometimes I think I shoulda been born a Wildhammer.\n\nI still don't like the sight o' those other towers, though.  Reachin' up like that, ticklin' my tower's feet.  Here, take this torch, an' use it on the braziers atop those other towers.  They'll be sorry they ever built 'em to begin with.", sourceObjective = "Use the Torch of Retribution on the four towers surrounding the Cauldron.", completion = "Looks like ye know how to light things on fire!  An admirable trait in any {race}, for sure.", sourceObjectiveStatus = "unverified-source-field" }
quests[28030] = { id = 28030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Build a Better Bullet", description = "Those gorge-digging dwarves do at least one thing right: they make very high-quality bullets.  I've been unable to reproduce their results, so I've taken to stealing whatever bullets of theirs that I can find.\n\nYe want my help?  Get me a couple hundred bullets from those marksmen below.\n\nI'm sure they'll be happy to give ye their bullets one at a time, but you might find it faster just to look for the crates filled with them.", sourceObjective = "Obtain 200 Dark Iron Bullets.", progress = "A real {class} woulda caught the bullets with his teeth.", completion = "I'll just divvy these up amongst the guards.  Ye have my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[28031] = { id = 28031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Delivery for Brivelthwerp", description = "I have a new business partner, my best buddy, Brivelthwerp. Even as we speak, he's building up the infrastructure for our new ice cream empire!\n\nHe took our coolant tug, inventory, and employees southwest to the Sunken Dig Site. Unfortunately, I don't currently have a way to deliver something to him... something extremely important: our super-secret I-Scream Cryocannon!\n\nYou don't mind taking it to him, do you, {name}?", sourceObjective = "Deliver the I-Scream Cryocannon to Brivelthwerp at the Sunken Dig Site in Thousand Needles.", progress = "That's not what I think it is? Is it?!", completion = "That must be the new I-Scream Cryocannon! Ain't she a beauty?!\n\n<Brivelthwerp eyes you shrewdly.>\n\nI'm going to let you in on a secret, my good friend: the groundwork for a vast mercantile empire is being laid right here!\n\nTell me... how do you feel about ice cream?", sourceObjectiveStatus = "unverified-source-field" }
quests[28032] = { id = 28032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mysteries of the Fire-Gizzard", description = "There's so much we don't know about the incendosaurs.  Where did they come from?  How do they survive out here on the flats?  And why do they taste so bad?\n\nThe key to understanding these prehistoric beasts, I believe, starts with the fire-gizzard.  Every incendosaur has one.  I'd like a few of them to study.\n\nYou'll find incendosaurs circling the foot of Iron Summit, mostly to the west.", sourceObjective = "Obtain 6 Fire-Gizzards.", progress = "I'm finally getting my hands on those lizard gizzards!", completion = "Ooh, these are nice.  Now, leave me alone with my gizzards.  I've got studying to do!\n\n<Agnes starts to poke the gizzards with a stick.>\n\nYes, very interesting.  Very interesting indeed...", sourceObjectiveStatus = "unverified-source-field" }
quests[28033] = { id = 28033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deceit", description = "What?  Why're you still here?  Oh, did I promise that I'd help you and the Thorium Brotherhood in yer fight?\n\nI lied.\n\nI just can't spare the men right now.  I know I said I'd help, but there's absolutely no way you can convince me to leave Iron Summit right now.  Absolutely no way.", sourceObjective = "Find a way to convince Mountain-Lord Rendan to join the Thorium Brotherhood.", completion = "Well well well.  Look who come searching for Lunk this time!\n\nThis sounds like case for Lunk's unique brand of no-kill problem-solve.", sourceObjectiveStatus = "unverified-source-field" }
quests[28034] = { id = 28034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk's Adventure: Rendan's Weakness", description = "Lunk not smart, but Lunk notice things.  Today, Lunk notice that Mountain-Dwarf likes to watch people dance.\n\nLunk like to dance!  {name} like to dance!  Probably!\n\nMaybe we find some more dwarfs that like to dance.  Then we go talk to Mountain-Dwarf, and he will listen to {name}.", sourceObjective = "Speak with three Iron Summit Guards and ask them to join your dance.", progress = "I thought I told you that I wasn't interested.  Why are you still here?", completion = "Did I stutter?  I believe I clearly stated that I... won't...\n\nWow, ye've got some good moves there!  I'm impressed!", sourceObjectiveStatus = "unverified-source-field" }
quests[28035] = { id = 28035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mountain-Lord's Support", description = "Alright, alright!  If I knew ye could dance like that, I wouldn't'a asked ye to do all that stuff earlier.\n\nTell Overseer Oilfist that I'll be joinin' ye.  I'll meet ye in the slag pit, <lad/lass>!  With the combined forces of Thorium Point and Iron Summit, those gorge-dwarves won't know what hit 'em!", sourceObjective = "Report your success to Overseer Oilfist at Thorium Point in Searing Gorge.", completion = "So, Rendan's on our side?  About time that oaf came around.\n\nLet's get moving, then.", sourceObjectiveStatus = "unverified-source-field" }
quests[28036] = { id = 28036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Zul'farrak", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Zul'farrak, just west of Gadgetzan, immediately!\n\nGadgetzan is being threatened by the Sandfury trolls and their growing army! If you so choose, head to Zul'farrak and speak with Tran'rek to help the goblins out.", sourceObjective = "Speak with Tran'rek.", sourceObjectiveStatus = "unverified-source-field" }
quests[28037] = { id = 28037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Zul'farrak", description = "The Warchief has requested that any able-bodied adventurer head to Zul'farrak, just west of Gadgetzan, immediately!\n\nGadgetzan is being threatened by the Sandfury trolls and their growing army! If you so choose, head to Zul'farrak and speak with Tran'rek to help the goblins out.", sourceObjective = "Speak with Tran'rek.", sourceObjectiveStatus = "unverified-source-field" }
quests[28038] = { id = 28038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood in the Highlands", description = "You've got some fight in you, {class}. You might do well in the crucible.\n\nWhat!? You haven't heard of the Crucible of Carnage? That smarmy goblin Gurgthock and his troll sidekick have been plastering us with leaflets ever since he set up shop here in the Highlands. Champions from all over Azeroth fight to the death in there. You should gather up some friends and see how you fare.\n\nThe Crucible is just to the southwest. Look for Wodin the Troll-Servant somewhere in the middle of a ring of bones.", sourceObjective = "Talk to Wodin the Troll-Servant at the Crucible of Carnage in Twilight Highlands.", completion = "Hey, you're one big strong heap of {class}. Can you handle the crucible? We got bookies standing by!", sourceObjectiveStatus = "unverified-source-field" }
quests[28039] = { id = 28039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Maraudon", description = "The Warchief has requested that any able-bodied adventurer head to Maraudon, in western Desolace, immediately!\n\nHealing Maraudon from its current corruption would great help the entirety of Desolace! If you so choose, head to Maraudon and speak with Zaetar's Spirit, he will guide you.", sourceObjective = "Speak with Zaetar's Spirit.", sourceObjectiveStatus = "unverified-source-field" }
quests[28040] = { id = 28040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Maraudon", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Maraudon, in western Desolace, immediately!\n\nHealing Maraudon from its current corruption would great help the entirety of Desolace! If you so choose, head to Maraudon and speak with Zaetar's Spirit, he will guide you.", sourceObjective = "Speak with Zaetar's Spirit.", sourceObjectiveStatus = "unverified-source-field" }
quests[28041] = { id = 28041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bait and Throttle", description = "You can hold your own on the ground, {name}. I'll give you that.\n\nBut we Dragonmaw dominate the skies as well as land. Until you can prove to me you can handle a drake as well as a Dragonmaw, your Horde is nothing to me.\n\nLet's see if you can wrangle one back to Bloodgulch.\n\nFirst you'll need bait. Go out and kill one of the gryphons that wander the woods west or northeast of here. Make sure it's untamed! Drakes hate the stink of dwarf on their food.\n\nGet the gryphon carcass and you'll know what to do.", sourceObjective = "Get a Fresh Gryphon Carcass.", progress = "<You gather up the fresh carcass.>", completion = "<You gather up the fresh carcass.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28042] = { id = 28042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Delivery for Brivelthwerp", description = "I recently came into possession of something that needs to be delivered to a gnome that goes by the name, Brivelthwerp. It's more like Briveltwerp if you ask me.\n\nI want you to take it to him in the southwest, down at the Sunken Dig Site. He's up to something and there's moolah involved... I can smell it!\n\nKeep an eye on what he's doing, {name}, and see if you can't get a cut of his profits. A big cut!", sourceObjective = "Deliver the I-Scream Cryocannon to Brivelthwerp at the Sunken Dig Site in Thousand Needles.", progress = "That's not what I think it is? Is it?!", completion = "<Brivelthwerp eyes you up and down, but becomes overjoyed at the sight of the special delivery.>\n\nWelcome, friend, welcome! I'm going to give you the chance to get involved at the ground level of a once-in-a-lifetime opportuntity.\n\nThe entrepreneurial spirit knows nothing of the differences between the Alliance and the Horde!\n\nTell me... how do you feel about ice cream?", sourceObjectiveStatus = "unverified-source-field" }
quests[28043] = { id = 28043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Maim Your Dragon", description = "<You sling the gore-spattered gryphon corpse over your shoulder, its wings dragging to the ground.>\n\n<Highland Black Drakes roost just southwest of the Crucible of Carnage, along a ring of low mountain peaks.>\n\n<If you drop the gryphon corpse there, a drake is sure to start feeding. With its guard down, you should be able to attack it until it is weak enough to mount and fly.>", sourceObjective = "Lure in a Baited Black Drake, attack it until it is weak, and then ride it back to Bloodgulch.", completion = "That was an impressive aerial display, {name}, but I wish it had come at a better time.\n\nNarkrall is a great warrior, but he's also an impatient fool. He's about to get himself killed ... and we're about to lose one of our most important weapons in the battle for the Highlands!", sourceObjectiveStatus = "unverified-source-field" }
quests[28044] = { id = 28044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touch the Untouchable", description = "I've added a drop of my very own essence to the ooze. Look for a glowing sigil to the west, at the edge of Shadowlurk Ridge. Stand on it, concentrate, and pour this stuff all over yourself. It should be enough to shift you into the nether and let you see what's REALLY there.\n\nYou won't be alone... the satyr's treasure is being guarded by the biggest voidstalker they could summon. Defeat him, and the treasure is yours.\n\nAnd come back in one piece, or this crazy broad's gonna fry me!", sourceObjective = "Use the Phaseblood Potion at the Sigil of Tichondrius to shift into the nether, and search for the Claw of Tichondrius.", progress = "Can you hear me in there, {name}? Do you have the claw?", completion = "The Claw of Tichondrius...\n\nYou hold a piece of the very demon that led the Legion to these woods, {name}. Better for it to be in our hands than with the satyr.\n\nHold still. I'm going to pull you back to our plane and make sure you and the claw arrive here safely...", sourceObjectiveStatus = "unverified-source-field" }
quests[28045] = { id = 28045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Greatest Flavor in the World!", description = "Below us is a cave. It's huge! The perfect location for our new refrigerated vault. It's big enough to hold all of our inventory with room to grow.\n\nUnfortunately, when we were almost done equipping all of the pipes, bugs burrowed up out of nowhere and killed all of my employees!\n\nHow was I supposed to know?\n\nBut it gave me a great idea: silithid-flavored ice cream. We'll make a killing!\n\nAll I need now are the ingredients.", sourceObjective = "Collect 8 Scoops of Silithid Goo.", progress = "You got enough bug goo for the first batch?", completion = "Oh yeah! This is going to be the greatest flavor in the world!\n\nLook out, Tigule and Foror!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[28046] = { id = 28046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish The Job", description = "We have been trying to collect useful scraps from the front all week.  Every time we gather a batch to bring back to camp, we get assaulted by the restless infantry in the area.  Can you head over there and clear them out?", sourceObjective = "Kill 5 Restless Infantry at the Restless Front. You can find the front on the west side of the island, just before Forgotten Hill.", completion = "It's about time someone took those guys out.", sourceObjectiveStatus = "unverified-source-field" }
quests[28047] = { id = 28047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freezing the Pipes", description = "It's time to break out the I-Scream Cryocannon!\n\nWe lifted the tech from the frost cannons on the river boats. If it's one thing that we gnomes are good at, it's miniaturization by way of making everything else that much bigger!\n\nI need you to take the cannon down there into the cave and freeze the pipes we setup in the walls. That'll jumpstart them.", sourceObjective = "Use the I-Scream Cryocannon to freeze the four pipes inside the cave.", completion = "Do you hear that, {name}? That's the sweet hum of the refrigeration kicking in.\n\nWe'll be able to store our inventory down there in no time. Thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[28048] = { id = 28048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Smart One's Gotta Go", description = "There's some kind of smart brain bug in the back of the cave. It's in charge of all of the silithid down there.\n\nMy ice cream is melting! How am I supposed to launch my ice cream empire, and save my inventory, if that thing's in there?!", sourceObjective = "Slay the Hive Controller.", completion = "Outstanding! Nothing can stop us from being the greatest purveyors of ice cream in all of Azeroth!", sourceObjectiveStatus = "unverified-source-field" }
quests[28049] = { id = 28049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See the Invisible", description = "Yeah, yeah, your stuck-up mage friend there hit it on the nose. The imps over at Shadowlurk Ridge are hiding the key to the satyr's barrier in the nether. It's right there, but you can't see it or touch it unless you're shifted.\n\nI guess you're out of luck though, because only imps can phase shift! So you should just close your eyes, turn around, and let me go...\n\nIt was just a joke! Don't hurt me! I'll need slime from the cursed oozes around these ruins. Bring me enough to cover you from head to toe!", sourceObjective = "Collect 8 batches of Cursed Ooze from the Ruins of Constellas.", progress = "You got that slime?", completion = "Oh good, you're back! Don't leave me alone with her! She's crazy!\n\nGimme that, I'll have you seeing the invisible in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[28050] = { id = 28050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shark Tank", description = "I hate sharks.  All of my troops hate sharks too.  This is where you come in, {name}.\n\nI need you to head up to the Cape of Lost Hope and take out a huge shark named Tank.  Tank is not to be trifled with so I would bring a few friends if I were you.", sourceObjective = "You have been tasked to kill Tank, a large shark cruising the waters of the Cape of Lost Hope. The cape can be found north of here, along the northern coastline.", progress = "I don't think you guys have a chance against that shark.", completion = "No way, you actually killed him?  We are having shark tacos tonight for sure!", sourceObjectiveStatus = "unverified-source-field" }
quests[28051] = { id = 28051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We All Scream for Ice Cream... and then Die!", description = "Don't get me wrong... I'm cheerful on the outside, but inside I'm just terribly torn to pieces. All of my friends and employees are dead.\n\nCould you do me a favor? Would you swim down there and attach the tug's tow hook to my dead employees? I'll reel them in.", sourceObjective = "Attach the tug's tow hook to 10 Dead Employees.", completion = "Thank you, {name}. They gave their lives for ice cream.", sourceObjectiveStatus = "unverified-source-field" }
quests[28052] = { id = 28052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Stir the Cauldron", description = "I'm putting you on a flying machine, {name}.\n\nYou'll be responsible for softening our landing into the slag pit.  Speak with your flight master here in Thorium Point, then fly down to the gorge.\n\nOnce you near your landing point, there will undoubtedly be hordes of Dark Iron dwarves waiting for you.  Use our flying machine's guns to take out as many of them as you can, then land at the cavern's entrance.  Rendan should be waiting for you by the time you arrive.", sourceObjective = "Speak to the Thorium Point flight master, then use the Brotherhood Flying Machine's guns to kill Cauldron Defenders until the area is safe for entry.", completion = "Well, here we are.\n\nI hope you're ready, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28053] = { id = 28053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunk Like Your Style", sourceObjective = "Lunk heared that you used the stone to banish fire-lizard.  You saved Gorge, and you didn't even kill!\n\nLunk so proud.  Lunk happy to be {name}'s teacher.\n\nMaybe you take this.  Lunk doesn't need it.  Lunk too busy adventuring!", sourceObjectiveStatus = "unverified-source-field" }
quests[28054] = { id = 28054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slavery is Bad", description = "Much like Overseer Maltorius, I'm a rich dwarf.  However, I earned my riches through hard work and wise decisions, not through slavery.\n\nOK fine, very little slavery.  Hardly any.\n\nAnyhow, the first thing that I see inside these caverns are slavedrivers and taskmasters.  I won't stand for this!  As you progress through the cavern, kill as many as you can.  Report your results to Evonice Sootsmoker, deeper within the Slag Pit.", sourceObjective = "Slay 10 Dark Iron Taskmasters or Dark Iron Slavers.", completion = "You've done good.  I don't like slavery either.", sourceObjectiveStatus = "unverified-source-field" }
quests[28055] = { id = 28055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet, Horrible Freedom", description = "Of course, we'll want to free as many slaves as we can while we're here.  Most of them will likely join forces with us, anxious to fight against their captors.\n\nHowever, sometimes you will find that slaves are resistant to being freed.  It's a strange phenomenon, often called \"Durnholde Syndrome\".\n\nEither way, you should try to free them.  If they resist, treat them as enemies.  Report your results to Evonice Sootsmoker, deeper within the Slag Pit.", sourceObjective = "Free 12 Slave Workers. If they resist, kill them.", progress = "Let's free a few more of these slaves before we move on.", completion = "Strange how so many slaves cope poorly with freedom.  It's a shame to have to do what we do, but such are the truths of war.\n\nNow, we must move on to more pressing tasks.", sourceObjectiveStatus = "unverified-source-field" }
quests[28056] = { id = 28056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Obsidion", description = "Overseer Maltorius is in charge here, but he's not the only dwarf of power within the Slag Pit.  Lathoric the Black and his horrifying golem, Obsidion, loom just down this corridor.\n\nInterfering with Lathoric's altar should summon both of them.  Find it, then summon Lathoric and kill him.  Report to Evonice Sootsmoker when you're finished.", sourceObjective = "Use the Altar of Suntara, then slay Lathoric the Black and Obsidion.", completion = "A fight well-fought, {name}!  I'm beginning to feel the tide turn.\n\nNow, when you're ready, let's hit these Dark Irons where it really hurts!", sourceObjectiveStatus = "unverified-source-field" }
quests[28057] = { id = 28057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill 'em With Sleep Deprivation", description = "It's a little known fact that dwarves, particularly of the Dark Iron variety, need rest! Lots of rest!\n\nNow I ask you; How can they sleep without pillows?  Exactly, {name}, they can't.  This is why you must steal their pillows.\n\nOnce you've finished your cushion-thievery, talk with Taskmaster Scrange.  He's a bit deeper in the cave, working on a covert project with Hansel.", sourceObjective = "Obtain 16 Dark Iron Pillows.", progress = "What?  Pillows?\n\nWhat?", completion = "I see Evonice is up to her old tricks again.  I guess I'll just... um... hang onto these pillows for a while.\n\nThe important part is that you're here.  We're going to need your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28058] = { id = 28058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Look at the Size of It!", description = "Well, well, well... Isn't this a surprise. The Chambermaid had a gigantic ornate pillow and now it's yours. Evonice Sootsmoker will definitely want to get her grubby little hands all over this item. Take it to her and see if she'll offer you any goodies for your trouble.", sourceObjective = "Take Chambermaid Pillaclencher's Pillow to Evonice Sootsmoker in the Searing Gorge.", progress = "That is one huge pillow! Where'd you get it from?", completion = "This is better than even I could have thought possible! The Chambermaid's magical pillow is mine! You better believe you're going to get a nice reward for this accomplishment, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28059] = { id = 28059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming The Keep", description = "Have you seen the keep on the north side of the island, {name}?  That is where Keep Lord Farson runs his operation from.\n\nFarson has a small group of dedicated followers and they have been giving us trouble since we got here.  We sent a small group to investigate and they reported back on his exact position within the keep.\n\nCan you finish him off for us?", sourceObjective = "You have been asked to kill Keep Lord Farson at the Farson Hold. Farson Hold can be found on the north side of the island.", completion = "You killed him?  We have been trying to take that guy out for weeks!  We thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28060] = { id = 28060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted Twilight Ties", description = "Hansel and I came here on a secret mission: kill Overseer Maltorius.  While our main goal still remains the same - defeating Archduke Calcinder - it can't hurt to take out the infamous overseer of the Slag Pit while we're here.\n\nProblem is, Hansel was only prepared to fight one dwarf, but it looks like Maltorius has a visitor... an emissary from the Twilight's Hammer!\n\nSpeak with Hansel and help him out.  Then proceed down this corridor and along the balcony outside to find Overseer Oilfist.", sourceObjective = "Speak with Hansel Heavyhands and help him assault Overseer Maltorius and Twilight-Lord Arkkus.", completion = "Twilight's Hammer, eh?  I should've expected as much.  I'm glad you arrived to help them out when you did.\n\nIt looks like, despite all odds, we've pressed our offensive to the doorstep of Calcinder's lair.  It's now time to finish the job.", sourceObjectiveStatus = "unverified-source-field" }
quests[28061] = { id = 28061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minions of Calcinder", description = "There is such a thing as digging too deep, {name}.  While you'll find the richest mineral veins deep below the surface, you'll also find the most evil creatures.\n\nLike fire elementals.\n\nCalcinder's minions roam the cavern ahead.  Every one of them holds a piece of Calcinder's evil within it.  Slay as many as you can, and show no remorse.", sourceObjective = "Slay 6 Searing Flamewraiths.", sourceObjectiveStatus = "unverified-source-field" }
quests[28062] = { id = 28062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Whence He Came", description = "Archduke Calcinder squirms in the back of this very cavern.  We are close to killing him... but that is not what we are going to do.\n\nSlaying Calcinder here means nothing.  His acolytes can easily revive him.  Instead, we are going to banish him.\n\nI asked you to gather a precious stone from the Twilight's Hammer earlier.  You will now use it against Calcinder.  Engage him, weaken him, then use this device on him.  He will be banished from this realm.\n\nGood luck, brave {name}.", sourceObjective = "Weaken Archduke Calcinder, then use the Sanctified Tripetricine to banish him.", sourceObjectiveStatus = "unverified-source-field" }
quests[28063] = { id = 28063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No Weapon Behind", description = "Battle supplies are hard to come by on this rock.  Every time we hold off another horde attack, it feels like we are fighting with sticks and stones.\n\nReports have come in that Keep Lord Farson on the north side of the island has a large stockpile of rifles that we could use.  Can you head down there and check it out?\n\nBe careful {name}, Farson's followers will do anything to protect him.", sourceObjective = "Retrieve 12 Rusty Rifles from Farson Hold on the north side of Tol Barad Peninsula.", progress = "Any luck with those rifles?", completion = "Thanks for rounding these up for us, {name}.  Kind of hard to fight a battle without any guns.", sourceObjectiveStatus = "unverified-source-field" }
quests[28064] = { id = 28064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the Brotherhood", description = "You should return to Thorium Point.  Overseer Oilfist and the rest of the Thorium Brotherhood will be wondering how you fared in the fight against Calcinder.", sourceObjective = "Report to Overseer Oilfist at Thorium Point in Searing Gorge.", completion = "Our task is complete, and it's all thanks to you, {name}.  I'd like to offer you your choice from our coffers.  In addition, I intend to make you a full-fledged member of our order.\n\nWelcome to the Thorium Brotherhood, {name}.  I'm proud to call you a brother.", sourceObjectiveStatus = "unverified-source-field" }
quests[28066] = { id = 28066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: The Sunken Temple", description = "The Warchief has requested that any able-bodied adventurer head to the Sunken Temple, not far from Stonard, immediately!\n\nThe Atal'ai trolls within are attempting to summon forth Hakkar the Soulflayer! If you so choose, head to the Sunken Temple and speak with the green dragon Lord Itharius, who is prepared to put an end to these dangerous trolls.", sourceObjective = "Speak with Lord Itharius.", sourceObjectiveStatus = "unverified-source-field" }
quests[28067] = { id = 28067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: The Sunken Temple", description = "King Varian Wrynn has requested that any able-bodied adventurer head to the Sunken Temple, not far from Marshtide Watch, immediately!\n\nThe Atal'ai trolls within are attempting to summon forth Hakkar the Soulflayer! If you so choose, head to the Sunken Temple and speak with the green dragon Lord Itharius, who is prepared to put an end to these dangerous trolls.", sourceObjective = "Speak with Lord Itharius.", sourceObjectiveStatus = "unverified-source-field" }
quests[28068] = { id = 28068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackrock Depths", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Blackrock Depths, northwest of Morgan's Vigil, immediately!\n\nThe Dark Iron dwarves pose a serious threat to the citizens of Redridge! If you so choose, head to Blackrock Depths and speak with Morgan, who has returned from her extended absence and wishes to enact her vengeance on the Dark Iron nation.", sourceObjective = "Speak with Morgan.", completion = "You look eager to kill a few hundred Dark Irons in justice's name.\n\nPerfect.", sourceObjectiveStatus = "unverified-source-field" }
quests[28069] = { id = 28069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackrock Depths", description = "The Warchief has requested that any able-bodied adventurer head to Blackrock Depths, west of Flame Crest, immediately!\n\nThe Dark Iron dwarves have already attacked Alliance-held Redridge, and if left unchecked, may soon threaten our few Horde footholds in southern Azeroth.\n\nIf you so choose, head to Blackrock Depths and speak with High Executioner Nuzrak, who is reforming the Kargath Expeditionary Force to finish off the Dark Irons once and for all.", sourceObjective = "Speak with High Executioner Nuzrak.", completion = "We've managed to take this small area, but to do anything more we'll need your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28070] = { id = 28070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackrock Spire", description = "The Warchief has requested that any able-bodied adventurer head to Blackrock Spire, west of Flame Crest, immediately!\n\nNefarian's armies and Rend Blackhand's followers threaten the very existence of the Horde! If you so choose, head to Blackrock Spire and speak with Acride, our only contact within that may be able to help us stop the impending invasion.", sourceObjective = "Speak with Acride.", sourceObjectiveStatus = "unverified-source-field" }
quests[28071] = { id = 28071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Blackrock Spire", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Blackrock Spire, northwest of Morgan's Vigil, immediately!\n\nNefarian's armies and Rend Blackhand's followers threaten the entirety of His Majesty's kingdom! If you so choose, head to Blackrock Spire and speak with Acride, our only contact within that may be able to help us stop the impending invasion.", sourceObjective = "Speak with Acride.", sourceObjectiveStatus = "unverified-source-field" }
quests[28072] = { id = 28072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Dire Maul Warpwood Quarter", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Dire Maul's Warpwood Quarter, east of Feathermoon Stronghold, immediately!\n\nAlzzin the Wildshaper has corrupted the area and could take over the entire Maul! If you so choose, head to the Warpwood Quarter and speak with Furgus Warpwood, one of the few uncorrupt beings left inside alive.", sourceObjective = "Speak with Furgus Warpwood.", sourceObjectiveStatus = "unverified-source-field" }
quests[28073] = { id = 28073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Dire Maul Warpwood Quarter", description = "The Warchief has requested that any able-bodied adventurer head to Dire Maul's Warpwood Quarter, west of Camp Mojache, immediately!\n\nAlzzin the Wildshaper has corrupted the area and could take over the entire Maul! If you so choose, head to the Warpwood Quarter and speak with Furgus Warpwood, one of the few uncorrupt beings left inside alive.", sourceObjective = "Speak with Furgus Warpwood.", sourceObjectiveStatus = "unverified-source-field" }
quests[28074] = { id = 28074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Dire Maul Capital Gardens", description = "The Warchief has requested that any able-bodied adventurer head to Dire Maul's Capital Gardens, west of Camp Mojache, immediately!\n\nThe fallen Highborne Prince Tortheldrin is using the massive demon Immol'thar to control the area! If you so choose, head to the Capital Gardens and speak with Estulan, a recently discovered pure Highborne seeking to reclaim the fallen city for his people.", sourceObjective = "Speak with Estulan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28075] = { id = 28075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Dire Maul Capital Gardens", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Dire Maul's Capital Gardens, east of Feathermoon Stronghold, immediately!\n\nThe fallen Highborne Prince Tortheldrin is using the massive demon Immol'thar to control the area! If you so choose, head to the Capital Gardens and speak with Estulan, a recently discovered pure Highborne seeking to reclaim the fallen city for his people.", sourceObjective = "Speak with Estulan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28076] = { id = 28076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Northern Dire Maul", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Northern Dire Maul, east of Feathermoon Stronghold, immediately!\n\nKing Gordok and his growing army of Gordok ogres pose the largest and most powerful threat in the area to us! If you so choose, head to Northern Dire Maul and speak with the Druid of the Talon already sent there as a forward scout.", sourceObjective = "Speak with the Druid of the Talon.", sourceObjectiveStatus = "unverified-source-field" }
quests[28077] = { id = 28077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Northern Dire Maul", description = "The Warchief has requested that any able-bodied adventurer head to Northern Dire Maul, west of Camp Mojache, immediately!\n\nKing Gordok and his growing army of Gordok ogres pose the largest and most powerful threat in the area to us! If you so choose, head to Northern Dire Maul and speak with the Stonemaul Ogre already sent there as a forward scout.", sourceObjective = "Speak with the Stonemaul Ogre.", sourceObjectiveStatus = "unverified-source-field" }
quests[28078] = { id = 28078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Stratholme Main Gate", description = "The Warchief has requested that any able-bodied adventurer head to Stratholme's main gate, due north from Plaguewood, immediately!\n\nThe Dreadlord Balnazzar has slain the Scarlet Crusade and resurrected them as the Risen! If you so choose, head to the main gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", sourceObjective = "Speak with Crusade Commander Eligor Dawnbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28079] = { id = 28079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Stratholme Main Gate", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Stratholme's main gate, due north from Plaguewood, immediately!\n\nThe Dreadlord Balnazzar has slain the Scarlet Crusade and resurrected them as the Risen! If you so choose, head to the main gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", sourceObjective = "Speak with Crusade Commander Eligor Dawnbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28080] = { id = 28080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Stratholme Service Gate", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Stratholme's service gate, just northwest of the Northpass Tower, immediately!\n\nLord Aurius Rivendare, former paladin of the Silver Hand and recently resurrected son of none other than Baron Rivendare himself, now leads the remaining scourge forces there! If you so choose, head to the service gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", sourceObjective = "Speak with Crusade Commander Eligor Dawnbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28081] = { id = 28081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Stratholme Service Gate", description = "The Warchief has requested that any able-bodied adventurer head to Stratholme's service gate, just northwest of the Northpass Tower, immediately!\n\nLord Aurius Rivendare, former paladin of the Silver Hand and recently resurrected son of none other than Baron Rivendare himself, now leads the remaining scourge forces there! If you so choose, head to the service gate and speak with Crusade Commander Eligor Dawnbringer, leader of the Argent Crusade effort to retake Stratholme for its true owners.", sourceObjective = "Speak with Crusade Commander Eligor Dawnbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28082] = { id = 28082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scholomance", description = "King Varian Wrynn has requested that any able-bodied adventurer head to Scholomance, east of Andorhal, immediately!\n\nRas Frostwhisper and Darkmaster Gandling are still hard at work training powerful sorcerers for the scourge! If you so choose, head to Scholomance and speak with Weldon Barov, last living son of Barov and heir to much of the surrounding lands.", sourceObjective = "Speak with Weldon Barov.", sourceObjectiveStatus = "unverified-source-field" }
quests[28083] = { id = 28083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Scholomance", description = "The Warchief has requested that any able-bodied adventurer head to Scholomance, east of Andorhal, immediately!\n\nRas Frostwhisper and Darkmaster Gandling are still hard at work training powerful sorcerers for the scourge! If you so choose, head to Scholomance and speak with Alexi Barov, one of the last heirs to the Barov fortune and our contact within the dark school.", sourceObjective = "Speak with Alexi Barov.", sourceObjectiveStatus = "unverified-source-field" }
quests[28084] = { id = 28084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Might of the Krom'gar", sourceObjective = "You may now make use of the Krom'gar stockpile, {name}! For a small fee I will sell you armaments of battle, useful for crushing your enemies! The availability of what I sell depends upon your rank in the army. Visit my shop whenever you earn a new rank.\n\nLOK'TAR OGAR!", sourceObjectiveStatus = "unverified-source-field" }
quests[28085] = { id = 28085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Highperch", description = "Thank you for your help, {name}. You should speak with Pao'ka Swiftmountain at Highperch to the southwest.\n\nPerhaps he will know the whereabouts of the Elder Crone?", sourceObjective = "Speak with Pao'ka Swiftmountain at Highperch in Thousand Needles.", completion = "I know nothing of the Elder Crone, Magatha. What I do know is that the Twilight's Hammer is destroying Highperch.\n\nWill you help me to stop them, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[28086] = { id = 28086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free the Pridelings", description = "The trappers are rounding up all of the young wind riders. {name}, will you go out there and free the pridelings?", sourceObjective = "Free 12 Highperch Pridelings.", completion = "They're precious. One day they'll grow strong, but until then, they must be protected.", sourceObjectiveStatus = "unverified-source-field" }
quests[28087] = { id = 28087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to all Trappers!", description = "There's only one answer for those filthy Twilight's Hammer trappers! Death!\n\nBring me their nets, {name}.", sourceObjective = "Collect 8 Trapper Nets.", progress = "What insanity could drive someone to do such horrible things?", completion = "There'll be no more trapping this day!", sourceObjectiveStatus = "unverified-source-field" }
quests[28088] = { id = 28088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Release Heartrazor", description = "The Twilight's Hammer have the alpha male of Highperch pinned down. You must head east up the ramp and release Heartrazor before the pride loses its patriarch!", sourceObjective = "Release Heartrazor from all bonds restraining him.", completion = "The great Heartrazor is a majestic creature. He has told me of his gratitude and fondness for you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28089] = { id = 28089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Hillsbrad Foothills!", description = "All able bodied members of the Horde are hereby ordered to report to High Executor Darthalia at Southpoint Gate in Hillsbrad Foothills. The Forsaken war machine marches ever onward, securing Lordaeron for the Horde!\n\nTo reach Southpoint Gate you must follow the road south through Silverpine Forest and take the east fork leading into Hillsbrad Foothills.\n\nOnward, <brother/sister>! Destiny calls!", sourceObjective = "Report to High Executor Darthalia at Southpoint Gate in Hillsbrad Foothills.", completion = "I was wondering when reinforcements would show up. Suit up, {name}. It's time to dispense some justice!", sourceObjectiveStatus = "unverified-source-field" }
quests[28090] = { id = 28090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Goods", description = "The gates further down the canyon are shut. Our scouting revealed some kind of stone that they carry in chests in their caravans that they use to open the gates.\n\nGet down there and look for a chest key on the bodies of the guards. When you find it, use it on one of those chests on the caravan wagons and bring the gatestone back to me.", sourceObjective = "Retrieve a Twilight Caravan Gatestone. The Spearwardens should carry keys that can get you into the gatestone chests.", progress = "You know, we could probably just blow the gates, but knowing our demoman, we're probably better off dodging the risk.", completion = "Good going.\n\nDoesn't look like much, does it?", sourceObjectiveStatus = "unverified-source-field" }
